// Electrotherapy I (low and medium frequency) and physical modalities maintenance topics for the Dr. MGR BPT syllabus. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"el-current-types-uses", title:"Electric currents in therapy: types, basic physics and therapeutic uses", subject:"Electrotherapy", region:"General", stages:"steps",
  aliases:["types of current","classification of electrotherapy currents","low medium high frequency current","direct and alternating current","pulsed current","therapeutic uses of electricity"],
  simple:"Electric current is a flow of charged particles. In therapy we use direct current, alternating current and pulsed currents, grouped by frequency into low, medium and high frequency. Each type has a different effect: chemical, nerve and muscle stimulation, or deep heating.",
  flow:["Charges flow when a potential difference drives them","Current shape: direct, alternating or pulsed","Frequency groups: low, medium, high","Body tissues act as electrolytic conductors","Effects: chemical, stimulating or heating","Choose the current that gives the wanted effect"],
  exam:[
    {h:"Definition", p:["Electric current is the rate of flow of electric charge through a conductor; unit ampere (1 A = 1 coulomb per second).","In metal wires the carriers are electrons; in body tissues the carriers are ions in tissue fluid, so the body behaves as an electrolytic conductor."]},
    {h:"Basic physics", p:["Potential difference (volt) drives current; resistance (ohm) opposes it; Ohm's law V = I x R.","Skin is the main resistance (dry skin very high, wet skin much lower); medium and high frequencies meet less skin impedance because skin acts like a capacitor.","Current density = current / electrode area; small electrodes concentrate current and give stronger effects and more risk of burns.","Key pulse terms: amplitude, pulse (phase) duration, frequency (pulses per second, Hz), rise and fall time, duty cycle (on time / total time)."]},
    {h:"Classification by waveform", p:["Direct (galvanic) current: unidirectional; continuous (constant) or interrupted (IDC) into long pulses.","Alternating current: changes direction continuously, e.g. sinusoidal current; mains is 50 Hz in India.","Pulsed current: monophasic (e.g. HVPGS twin peaks, faradic-type), biphasic symmetrical or asymmetrical (most TENS and NMES), and polyphasic bursts (Russian current, burst TENS).","Modulations: surged, ramped, burst, sweep (frequency modulation)."]},
    {h:"Classification by frequency", p:["Low frequency: 1-1000 Hz, e.g. faradic, IDC, TENS, HVPGS, diadynamic, sinusoidal; stimulate nerve and muscle directly.","Medium frequency: 1000-10000 Hz (some texts up to 100 kHz), e.g. interferential (about 4000 Hz) and Russian current (2500 Hz); pass skin comfortably.","High frequency: above 100000 Hz, e.g. short wave diathermy (27.12 MHz) and microwave (2450 MHz); too fast to stimulate nerves, so they produce heat."]},
    {h:"Effects and therapeutic uses", p:["Chemical effects of direct current: acid under anode, alkali under cathode; used in iontophoresis, risk of chemical burns.","Stimulating effects: sensory nerve stimulation for pain relief (TENS, IFT); motor nerve stimulation for muscle re-education and strengthening (faradic, NMES, Russian, FES); direct muscle stimulation of denervated muscle (IDC).","Other uses: oedema reduction (muscle pump, HVPGS), wound healing (HVPGS, low-intensity DC), electrodiagnosis (SD curve, NCS), biofeedback.","Thermal effects of high frequency currents: deep heating with SWD and microwave."]},
    {h:"General dangers and contraindications", p:["Dangers: electric shock, chemical burns (DC), thermal burns (high frequency), overdose and muscle fatigue, skin irritation.","Contraindications common to stimulating currents: demand pacemaker, anterior neck and carotid sinus, pregnant uterus, active DVT, malignancy, broken skin, impaired sensation or cognition, active bleeding."]},
    {h:"Conclusion", p:["Knowing the waveform and frequency of a current predicts its effect; matching current to the goal (chemical, stimulating or heating) is the basis of safe, effective electrotherapy."]}
  ],
  tip:"Draw three small graphs of current against time: a flat line above zero (direct), a sine wave (alternating) and spaced rectangles (pulsed). Under them draw a frequency bar: low (below 1 kHz), medium (1-10 kHz), high (above 100 kHz) with one example in each.",
  evidence:[["TENS for acute and chronic pain","Pain reduction during and immediately after use compared with placebo","Moderate"],["NMES added to exercise for quadriceps weakness","Better early strength after knee surgery","Moderate"],["Electrical stimulation for chronic wounds","Faster healing of chronic ulcers in pooled trials","Low-moderate"]],
  evidenceSource:"Robertson, Ward, Low and Reed, Electrotherapy Explained; Cameron, Physical Agents in Rehabilitation",
  outcomes:[["NPRS or VAS","Pain relief from sensory stimulation"],["MMT or dynamometry","Strength change with motor stimulation"],["Wound surface area","Healing response to stimulation"]],
  recent:["Johnson MI et al. (BMJ Open 2022) pooled several hundred randomised trials and found TENS reduced pain intensity during or immediately after treatment compared with placebo, though certainty was low."],
  mnemonic:{word:"CSH", items:[["C","Chemical effect: direct current"],["S","Stimulating effect: low and medium frequency"],["H","Heating effect: high frequency"]], extra:"Frequency up, skin resistance down; above about 100 kHz nerves cannot follow, so only heat remains."},
  example:"In a Coimbatore college clinic, a student sets up TENS (low frequency) for a patient with chronic neck pain, IFT (medium frequency) for knee OA pain, and SWD (high frequency) for a stiff hip, and explains why each current was chosen.",
  flags:["Demand pacemaker or implanted defibrillator","Anterior neck, carotid sinus or over the pregnant uterus","Broken skin or impaired sensation under electrodes","Chemical burns with direct current at high current density"],
  viva:[["What is the frequency range of medium frequency currents?","About 1000-10000 Hz (some authors up to 100 kHz), e.g. IFT at about 4000 Hz."],["Why do high frequency currents not stimulate nerves?","Each pulse is far too short for the nerve membrane to depolarise to threshold, so only heating occurs."],["What happens under the cathode with direct current?","An alkaline reaction (sodium hydroxide forms), which can cause a chemical burn."]],
  refs:[{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Electrical stimulation, basic principles."},{b:"cameron", ch:"Introduction to electrotherapy"},{c:"Johnson MI, Paley CA, Jones G, Mulvey MR, Wittkopf PG. Efficacy and safety of transcutaneous electrical nerve stimulation (TENS) for acute and chronic pain in adults: a systematic review and meta-analysis of 381 studies (the meta-TENS study). BMJ Open. 2022.", q:"meta-TENS study Johnson BMJ Open 2022"}],
  keywords:"types of current direct alternating pulsed low medium high frequency therapeutic uses electrotherapy classification",
  mcq:[["Interferential current is classified as:",["Low frequency current","High frequency current","Medium frequency current","Direct current"],2,"IFT uses carrier currents of about 4000 Hz, in the medium frequency range."],["Which effect is characteristic of continuous direct current?",["Chemical changes under electrodes","Deep heating","Ultrasound cavitation","Tetanic contraction at 50 Hz"],0,"Direct current causes electrolysis: acid under the anode and alkali under the cathode."]]
},
{
  id:"el-rmp-action-potential", title:"Resting membrane potential, action potential and propagation (basis of electrical stimulation)", subject:"Electrotherapy", region:"Nerve and muscle", stages:"steps",
  aliases:["RMP","action potential","nerve impulse","saltatory conduction","depolarisation","refractory period","propagation of impulse"],
  simple:"Nerve and muscle cells keep a small negative charge inside at rest. When a stimulus pushes this charge to threshold, sodium rushes in and an action potential fires and travels along the fibre. Electrical stimulation works by causing this depolarisation artificially under the electrode.",
  flow:["Na-K pump and potassium leak keep inside negative","Stimulus depolarises membrane to threshold","Sodium channels open: rapid depolarisation","Potassium outflow repolarises the membrane","Local currents spread the impulse along the fibre","Myelinated fibres conduct fast by saltatory conduction"],
  exam:[
    {h:"Resting membrane potential (RMP)", p:["The potential difference across the membrane at rest: about -70 mV in nerve and about -90 mV in skeletal muscle (inside negative).","Produced by unequal ion distribution (more K inside, more Na outside), selective permeability (membrane much more permeable to K at rest) and the Na-K ATPase pump (3 Na out, 2 K in).","Large negative proteins and phosphates trapped inside add to the negativity."]},
    {h:"Action potential: phases", p:["Threshold: about -55 mV; a stimulus below threshold gives only a local (graded) potential.","Depolarisation: voltage-gated Na channels open, Na enters, membrane rises to an overshoot of about +30 to +35 mV.","Repolarisation: Na channels inactivate and K channels open, K leaves; after-hyperpolarisation follows before RMP is restored.","All-or-none law: once threshold is reached the size of the action potential is constant."]},
    {h:"Refractory periods and accommodation", p:["Absolute refractory period: no second impulse can be produced (Na channels inactivated); limits maximum firing rate.","Relative refractory period: a stronger stimulus is needed.","Accommodation: if a stimulus rises slowly, Na channels inactivate before threshold is reached, so the nerve fails to fire; this is why slow-rising (triangular) pulses spare normal nerve and stimulate denervated muscle selectively."]},
    {h:"Propagation", p:["Local circuit currents flow from the active region to the neighbouring resting membrane and depolarise it to threshold.","Unmyelinated fibres: continuous, slow conduction (about 0.5-2 m/s).","Myelinated fibres: saltatory conduction from node to node of Ranvier, fast (up to about 120 m/s) and energy efficient.","Conduction velocity increases with fibre diameter and myelination; demyelination slows or blocks conduction."]},
    {h:"Applied relevance to electrotherapy", p:["Under the cathode the outside of the membrane becomes more negative, so the membrane depolarises: the cathode is the usual active (stimulating) electrode.","Under the anode the membrane hyperpolarises (anodal block can occur at high intensity).","Large-diameter fibres have lower thresholds, so with rising intensity the order is sensory (A-beta), motor, then pain (A-delta, C) fibres; this underlies TENS and NMES dosage.","Artificial stimulation recruits large motor units first and synchronously, so NMES fatigues muscle faster than voluntary contraction."]},
    {h:"Conclusion", p:["Every electrotherapy current that stimulates nerve or muscle works by depolarising the membrane to threshold; understanding RMP, threshold, refractory period and accommodation explains pulse duration, frequency and waveform choices."]}
  ],
  tip:"Draw the action potential graph: y axis membrane potential (-90 to +40 mV), x axis time (ms). Mark RMP, threshold, depolarisation (Na in), overshoot, repolarisation (K out), hyperpolarisation and the absolute and relative refractory periods.",
  evidence:[["Large fibres have lower electrical thresholds","Explains sensory before motor before pain recruitment","Established physiology"],["NMES recruits motor units non-selectively and synchronously","Faster fatigue than voluntary contraction","Moderate (laboratory studies)"]],
  evidenceSource:"Guyton and Hall, Textbook of Medical Physiology; Robertson et al., Electrotherapy Explained",
  outcomes:[["Nerve conduction velocity","Speed of propagation in tested nerve"],["Rheobase and chronaxie","Excitability of nerve and muscle"]],
  recent:["Research on NMES increasingly uses wide-pulse, higher-frequency protocols to add central (reflex) recruitment of motor units, aiming to reduce the fatigue of purely peripheral, synchronous recruitment."],
  mnemonic:{word:"NaK", items:[["Na in","Depolarisation"],["K out","Repolarisation"],["Pump","3 Na out, 2 K in keeps RMP"]], extra:"Cathode excites, anode inhibits."},
  example:"A Chennai student explains to her batchmates why a slowly rising triangular pulse makes a denervated tibialis anterior contract while the normal peroneal muscles stay quiet: the healthy nerve accommodates.",
  flags:["High current density under small electrodes can burn skin","Stimulating over the carotid sinus can trigger reflex bradycardia","Stimulation near the heart in patients with pacemakers"],
  viva:[["What is the RMP of a skeletal muscle fibre?","About -90 mV."],["What is saltatory conduction?","Jumping of the impulse from one node of Ranvier to the next in myelinated fibres, making conduction fast."],["Which electrode usually stimulates and why?","The cathode, because it depolarises the nerve membrane beneath it."]],
  refs:[{b:"guyton", ch:"Membrane potentials and action potentials"},{c:"Sembulingam K, Sembulingam P. Essentials of Medical Physiology. Chapter: Resting membrane potential and action potential."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Nerve and muscle stimulation."}],
  keywords:"resting membrane potential action potential threshold refractory period accommodation saltatory conduction propagation cathode depolarisation",
  mcq:[["Accommodation of nerve is best demonstrated with which pulse?",["Rectangular pulse","Very short 50 microsecond pulse","Biphasic symmetrical pulse","Triangular slowly rising pulse"],3,"A slowly rising pulse lets Na channels inactivate before threshold, so normal nerve fails to fire."],["The overshoot of the nerve action potential reaches about:",["-90 mV","+35 mV","-55 mV","+120 mV"],1,"The membrane briefly becomes positive inside, about +30 to +35 mV."]]
},
{
  id:"el-hvpgs-diadynamic-fes", title:"HVPGS, diadynamic currents and functional electrical stimulation (FES)", subject:"Electrotherapy", region:"Nerve, muscle and wounds", stages:"steps",
  aliases:["HVPGS","high voltage pulsed galvanic stimulation","high volt","diadynamic current","Bernard currents","FES","functional electrical stimulation","foot drop stimulator"],
  simple:"HVPGS uses very short twin-peaked pulses at high voltage but low average current, mainly for wounds, oedema and pain. Diadynamic currents are rectified 50 or 100 Hz sine waves used in the past for pain. FES stimulates nerves at the right moment during a task, such as lifting the foot while walking after stroke.",
  flow:["HVPGS: twin peaks, up to 500 V, low average current","Used for wound healing, oedema and pain","Diadynamic: rectified 50 Hz and 100 Hz sine waves","Diadynamic has DC component: risk of chemical burn","FES: stimulation timed to a functional task","Foot drop: heel switch triggers peroneal stimulation"],
  exam:[
    {h:"HVPGS: physics and parameters", p:["Monophasic twin-peak pulses, each peak very short (about 5-20 microseconds, pair about 100 microseconds); peak voltage up to about 500 V (commonly 100-500 V).","Frequency 1-120 Hz; average current very low (about 1-1.5 mA), so little risk of chemical burn despite being monophasic.","Polarity can be chosen: cathode or anode as the treatment electrode over a large dispersive pad."]},
    {h:"HVPGS: uses and dosage", p:["Chronic wounds and pressure ulcers: electrode over saline-moistened gauze in the wound, 100-120 Hz, sensory-level intensity, 45-60 minutes, 5-7 days a week; cathode often used first for infected or early wounds, anode later (protocols vary).","Acute oedema: cathode, about 120 Hz, submotor intensity, about 30 minutes, early after injury (mainly animal evidence).","Pain relief (as TENS-like sensory stimulation) and muscle contraction at motor intensity."]},
    {h:"Diadynamic (Bernard) currents", p:["Half-wave rectified 50 Hz sine (monophase fixe, MF) and full-wave rectified 100 Hz sine (diphase fixe, DF), often superimposed on a small galvanic base current.","Modulations: CP (courtes periodes: MF and DF alternate every 1 s), LP (longues periodes: MF with slowly modulated DF over about 6 s), RS (rhythme syncope: MF 1 s on, 1 s off) for muscle stimulation.","Uses: pain, sprains and haematoma (DF then CP), periarthritis; mostly historical, with little modern trial evidence.","Danger: because of the unidirectional component, chemical burns can occur; limit time (a few minutes per mode) and check skin."]},
    {h:"FES: principle and parameters", p:["Stimulation of intact peripheral (lower motor) nerves to produce a useful movement during a functional task in upper motor neuron lesions (stroke, SCI, MS, CP).","Typical parameters: frequency 20-50 Hz (often 30-40 Hz), pulse duration 200-300 microseconds, ramp up about 1 s, intensity for a functional contraction; triggered by a switch, sensor or timer.","Requires intact lower motor neurons and enough passive range; not useful in denervated muscle."]},
    {h:"FES applications", p:["Drop foot: common peroneal nerve stimulated at the fibular head during swing, triggered by heel-off switch; gives dorsiflexion and eversion.","Hemiplegic shoulder subluxation: supraspinatus and posterior deltoid.","Hand opening and grasp (wrist and finger extensors), FES cycling and rowing in SCI, FES-assisted standing and walking.","Benefits: orthotic effect, possible therapeutic carry-over, better cardiovascular fitness and muscle bulk in SCI."]},
    {h:"Dangers and contraindications", p:["General: pacemaker, anterior neck, pregnant uterus, malignancy, DVT, broken skin (except wound protocols), impaired sensation, epilepsy (caution).","FES: autonomic dysreflexia in lesions above T6, fatigue, skin irritation, falls, fractures in osteoporotic SCI limbs during cycling or standing."]},
    {h:"Conclusion", p:["HVPGS is supported for chronic wound healing, diadynamic currents are mainly historical, and FES is a useful, task-specific orthotic and training tool for drop foot and SCI when lower motor neurons are intact."]}
  ],
  tip:"Draw three waveforms side by side: twin narrow spikes with a long gap (HVPGS), a row of half sine humps (MF 50 Hz) and continuous humps (DF 100 Hz), and a leg with a heel switch wired to a cuff below the knee (FES for foot drop).",
  evidence:[["Electrical stimulation for chronic wounds and pressure ulcers","Faster healing of chronic wounds in pooled trials","Moderate"],["FES for drop foot after stroke","Improves walking speed when worn, similar to an AFO","Moderate"],["Diadynamic currents for pain","Few good-quality trials","Very low"]],
  evidenceSource:"Robertson et al., Electrotherapy Explained; NICE interventional procedure guidance IPG278 (FES for drop foot of central neurological origin)",
  outcomes:[["Wound surface area","Wound healing rate"],["10 metre walk test","Walking speed with FES"],["Physiological cost index","Energy cost of walking"]],
  recent:["NICE interventional procedure guidance IPG278 (2009) supports FES for drop foot of central neurological origin with normal arrangements for consent and audit.","International pressure injury guidelines (EPUAP/NPIAP 2019) include electrical stimulation as an option for recalcitrant pressure injuries."],
  mnemonic:{word:"HDF", items:[["H","High volt: twin spikes, wounds and oedema"],["D","Diadynamic: MF 50, DF 100, CP, LP, RS"],["F","FES: function, 20-50 Hz, intact LMN"]], extra:"Diadynamic has a DC part: watch for chemical burns."},
  example:"A 55-year-old auto driver in Madurai with drop foot after stroke uses a peroneal FES unit with a heel switch; his clearance improves and he stops tripping on the clinic steps.",
  flags:["Autonomic dysreflexia during FES in SCI above T6","Chemical burn with diadynamic current","Pacemaker or stimulation over the anterior neck","Fragile osteoporotic bones during FES cycling or standing in chronic SCI"],
  viva:[["What is the peak voltage of HVPGS?","Up to about 500 V, but with very short twin pulses, so average current is low."],["Name the diadynamic modulations.","MF, DF, CP, LP and RS."],["Why does FES not work in a brachial plexus avulsion?","FES needs an intact lower motor neuron; denervated muscle needs long-duration IDC instead."]],
  refs:[{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapters: High voltage pulsed current; Functional electrical stimulation."},{b:"cameron", ch:"Electrical currents for tissue healing"},{c:"National Institute for Health and Care Excellence. Functional electrical stimulation for drop foot of central neurological origin. Interventional procedures guidance IPG278. 2009.", q:"NICE IPG278 functional electrical stimulation drop foot"}],
  keywords:"HVPGS high voltage pulsed current twin peak wound healing oedema diadynamic MF DF CP LP RS FES functional electrical stimulation drop foot peroneal",
  mcq:[["The waveform of HVPGS is:",["Monophasic twin-peak pulse","Biphasic symmetrical square pulse","Continuous direct current","Sinusoidal 4000 Hz"],0,"HVPGS uses paired very short monophasic spikes at high voltage."],["Which diadynamic current is half-wave rectified 50 Hz?",["DF","CP","MF","LP"],2,"Monophase fixe (MF) is half-wave rectified 50 Hz; DF is full-wave 100 Hz."]]
},
{
  id:"el-russian-medium-frequency", title:"Medium frequency currents: Russian current and 2-pole and 4-pole IFC", subject:"Electrotherapy", region:"Muscle and soft tissues", stages:"steps",
  aliases:["Russian current","Kots current","2500 Hz burst","medium frequency current","bipolar IFT","quadripolar IFT","10/50/10"],
  simple:"Medium frequency currents (about 1-10 kHz) pass the skin easily, so they feel more comfortable. Russian current is a 2500 Hz current broken into 50 bursts per second, used for strengthening. Interferential current mixes two medium frequency currents (4-pole) or modulates one inside the machine (2-pole) to give a low frequency effect in the tissues.",
  flow:["Medium frequency meets low skin impedance","Russian: 2500 Hz carrier in 50 Hz bursts","Strong, tolerable contraction for strengthening","IFC 4-pole: two circuits interfere in tissue","IFC 2-pole: premodulated in the machine","Low frequency AMF gives the physiological effect"],
  exam:[
    {h:"Definition and principle", p:["Medium frequency currents are alternating currents of about 1000-10000 Hz.","Skin impedance falls as frequency rises (skin behaves like a capacitor: Xc = 1 / 2 pi f C), so more current reaches deep tissue with less sensory discomfort.","A single medium frequency cycle is too short to stimulate a nerve on its own; nerves respond to the low frequency modulation (bursts or beats)."]},
    {h:"Russian current", p:["Described by Kots (1970s): 2500 Hz sinusoidal or triangular carrier, burst-modulated at 50 bursts per second (10 ms burst, 10 ms interval, 50 percent duty cycle).","Classic 10/50/10 protocol: 10 s contraction, 50 s rest, 10 contractions per session, at maximal tolerated intensity; usually once daily, several times a week.","Aim: strengthening by producing contractions of a high percentage of maximal voluntary isometric force; good for quadriceps after ACL reconstruction or TKA.","Original claims of large strength gains in athletes were not reproduced; it is as effective as other well-dosed NMES, not superior."]},
    {h:"Interferential current: 4-pole (quadripolar)", p:["Two independent circuits, e.g. 4000 Hz and 4100 Hz, placed so they cross in the target area.","Where they meet, the currents interfere and produce an amplitude modulated frequency (AMF or beat frequency) equal to the difference, here 100 Hz.","Static field: full (100 percent) modulation depth only along lines at 45 degrees to the circuits (clover-leaf pattern); vector or rotating field techniques move this zone."]},
    {h:"Interferential current: 2-pole (bipolar, premodulated)", p:["One circuit, two electrodes; the modulation is produced inside the machine, so the current leaving the electrodes is already amplitude modulated.","Modulation depth is 100 percent throughout the current path, so the effect is predictable; useful for small areas and for muscle stimulation.","Disadvantage: tends to be more superficial and less comfortable than quadripolar at the same depth."]},
    {h:"Indications, dosage and contraindications", p:["Russian: strengthening, quadriceps inhibition, disuse atrophy; IFC: pain (AMF 80-150 Hz), muscle stimulation (AMF 10-50 Hz), oedema (low AMF).","IFC dosage: carrier 2000-4000 Hz, AMF and sweep chosen for the goal, strong comfortable intensity, 10-20 minutes.","Contraindications as for other stimulating currents: pacemaker, pregnancy (abdomen, pelvis, low back), malignancy, DVT, infection, anterior neck, impaired sensation, metal implants (caution)."]},
    {h:"Conclusion", p:["Medium frequency currents trade low skin impedance for comfort; Russian current is a form of high-intensity NMES for strength, and IFC gives low frequency effects in deeper tissue using bipolar or quadripolar methods."]}
  ],
  tip:"Draw a 2500 Hz sine wave chopped into 10 ms bursts with 10 ms gaps (Russian). Then draw a knee with four electrodes in two crossing circuits (A1-A2 and B1-B2) and shade the clover-leaf zones at 45 degrees where full modulation occurs.",
  evidence:[["NMES (including Russian) added to exercise after TKA or ACL surgery","Better quadriceps strength in the early months","Moderate"],["Russian versus other NMES waveforms","No clear superiority; pulsed currents often equal or better","Low-moderate"],["IFC added to other treatment for musculoskeletal pain","Short-term pain reduction","Low-moderate"]],
  evidenceSource:"Ward and Shkuratova, Phys Ther 2002; Fuentes et al., Phys Ther 2010; Robertson et al., Electrotherapy Explained",
  outcomes:[["Isometric dynamometry","Quadriceps strength"],["Lag test and SLR","Quadriceps activation"],["NPRS","Pain relief with IFC"]],
  recent:["Ward and Shkuratova (Phys Ther 2002) reviewed the early Russian experiments and showed many original claims could not be verified, encouraging standard NMES dosing instead.","Fuentes et al. (Phys Ther 2010) meta-analysis found IFC was more helpful as an add-on to other treatment than as a stand-alone treatment."],
  mnemonic:{word:"Russian 2.5-50-10", items:[["2.5","2500 Hz carrier"],["50","50 bursts per second"],["10/50/10","10 s on, 50 s off, 10 reps"]], extra:"IFC: 4-pole interferes in the tissue, 2-pole is premodulated in the machine."},
  example:"A 24-year-old kabaddi player in Pune with quadriceps lag after ACL reconstruction receives Russian current 10/50/10 to the quadriceps with active knee extension in a long-sitting position.",
  flags:["Pacemaker or implanted defibrillator","Over the pregnant uterus or low back in pregnancy","Malignancy, DVT or infection in the area","Muscle soreness from maximal-intensity Russian current"],
  viva:[["What is the carrier frequency of Russian current?","2500 Hz, burst-modulated at 50 Hz."],["Where is modulation depth 100 percent in static quadripolar IFC?","Along the diagonals at 45 degrees to the two circuits."],["Why are medium frequencies more comfortable?","Skin capacitive impedance falls as frequency rises, so less current density is needed at the skin."]],
  refs:[{c:"Ward AR, Shkuratova N. Russian electrical stimulation: the early experiments. Phys Ther. 2002;82:1019-1030.", q:"Ward Shkuratova Russian electrical stimulation early experiments"},{c:"Fuentes JP, Armijo Olivo S, Magee DJ, Gross DP. Effectiveness of interferential current therapy in the management of musculoskeletal pain: a systematic review and meta-analysis. Phys Ther. 2010;90:1219-1238.", q:"Fuentes interferential current musculoskeletal pain meta-analysis"},{b:"cameron", ch:"Electrical currents for muscle contraction"}],
  keywords:"medium frequency Russian current Kots 2500 Hz burst 10/50/10 interferential bipolar quadripolar premodulated AMF",
  mcq:[["The classic Russian current protocol is:",["2 s on, 2 s off, 100 contractions","10 s on, 50 s off, 10 contractions","Continuous for 30 minutes","1 s on, 10 s off, 3 contractions"],1,"Kots used 10 s contraction, 50 s rest, 10 repetitions."],["In bipolar (premodulated) IFC the modulation is produced:",["In the tissues by interference","By the patient's skin capacitance","By suction cups","Inside the machine before the electrodes"],3,"Bipolar IFC is premodulated in the machine, giving 100 percent modulation throughout."]]
},
{
  id:"el-faradic-effects", title:"Faradic current: physiological and therapeutic effects", subject:"Electrotherapy", region:"Innervated muscle", stages:"steps",
  aliases:["effects of faradic current","faradism effects","therapeutic uses of faradic current","faradic foot bath","faradism under pressure","muscle re-education"],
  simple:"Faradic current gives short pulses that excite sensory and motor nerves, so the patient feels prickling and the muscle contracts strongly. The contraction pumps blood and lymph, keeps the muscle working and teaches the patient how the movement feels. It only works when the nerve to the muscle is intact.",
  flow:["Short pulses (0.1-1 ms) at 50-100 Hz","Sensory nerves: prickling and mild erythema","Motor nerves: tetanic contraction of innervated muscle","Surging gives contraction and relaxation like exercise","Muscle pump improves venous and lymphatic return","Used to re-educate, prevent atrophy and reduce oedema"],
  exam:[
    {h:"Definition", p:["Faradic-type current: short-duration pulses of about 0.1-1 ms at about 50-100 Hz, usually surged, which stimulate intact motor and sensory nerves.","It does not stimulate denervated muscle, which needs much longer pulses."]},
    {h:"Physiological effects", p:["Sensory nerve stimulation: mild prickling; reflex vasodilation gives slight erythema under the electrodes.","Motor nerve stimulation: tetanic (fused) contraction because the frequency is above about 30 Hz; surging gives a rise, hold and fall like a voluntary contraction.","Effects of contraction: increased metabolism and local blood flow, increased venous and lymphatic return (muscle pump), maintenance of muscle bulk and properties.","Movement produced may stretch or loosen adhesions within soft tissue.","Minimal chemical effect because pulses are short and alternating or balanced in modern units."]},
    {h:"Therapeutic effects and uses", p:["Facilitating contraction when muscle is inhibited by pain or effusion, e.g. quadriceps after meniscectomy, TKA or knee effusion.","Muscle re-education: gives the sensation of correct movement, e.g. after prolonged immobilisation or in functional weakness.","Training a new action after tendon transfer, e.g. tibialis posterior transfer for foot drop.","Reducing oedema: faradism under pressure (limb bandaged, elevated, muscles surged), e.g. post-fracture swelling of the ankle.","Faradic foot bath: strengthens intrinsic foot muscles in flexible flat foot and weak arches.","Pelvic floor stimulation for weak pelvic floor and stress incontinence (with active training)."]},
    {h:"Dosage", p:["Surge on 1-2 s, rest 2-6 s initially (about 1:3), progressing as fatigue allows.","Intensity: strong but comfortable visible contraction; 3 sets of 10-30 contractions, daily.","Patient should attempt to contract with the current and continue active exercise."]},
    {h:"Contraindications and dangers", p:["Pacemaker, anterior neck, pregnant uterus, malignancy, active DVT, recent fracture where contraction would displace it, broken skin, impaired sensation, unreliable patient, epilepsy (caution).","Dangers: electric shock, burns from poor contact or small electrodes, muscle fatigue or soreness."]},
    {h:"Conclusion", p:["Faradic current is an aid to re-educating innervated muscle and reducing oedema; it is withdrawn as soon as good voluntary contraction returns."]}
  ],
  tip:"Draw a surged faradic train: pulses rising gradually to a peak, holding, falling, then a flat rest period. Label surge duration, rest, and pulse duration 0.1-1 ms. Next to it draw a leg in elevation with bandage and electrodes (faradism under pressure).",
  evidence:[["NMES with exercise for quadriceps inhibition after knee surgery","Better early strength and activation","Moderate"],["Faradism under pressure for oedema","Clinical tradition, little trial evidence","Very low"],["Faradic foot bath for flat foot","Little trial evidence","Very low"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy; Cameron, Physical Agents in Rehabilitation",
  outcomes:[["MMT","Grade of voluntary contraction"],["Quadriceps lag","Activation of quadriceps"],["Limb girth","Oedema reduction"]],
  recent:["Modern clinics deliver faradic-type stimulation with biphasic NMES units that allow precise ramp, on and off time settings rather than induction-coil faradic machines."],
  mnemonic:{word:"FARADIC", items:[["F","Facilitate inhibited muscle"],["A","Atrophy slowed"],["R","Re-education"],["A","After tendon transfer"],["D","Dropping oedema (under pressure)"],["I","Intrinsic foot muscles (foot bath)"],["C","Circulation improved by muscle pump"]], extra:"Needs an intact nerve supply."},
  example:"Two days after arthroscopic meniscectomy in Trichy, a 30-year-old teacher cannot set her quadriceps; surged faradic stimulation over the femoral nerve and VMO helps her achieve a full static quad contraction.",
  flags:["Denervated muscle: faradic will not work, use IDC","Pacemaker and anterior neck stimulation","Unstable fracture near the stimulated muscle","Broken skin or impaired sensation under electrodes"],
  viva:[["Why does faradic current produce tetanic contraction?","Its frequency (50-100 Hz) is above the fusion frequency of muscle, so twitches fuse."],["Why is faradic surged?","To produce contraction and relaxation, mimic voluntary contraction and delay fatigue."],["What is faradism under pressure?","Surged faradic stimulation of a bandaged, elevated limb to pump out oedema."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Faradic type current."},{b:"cameron", ch:"Electrical currents for muscle contraction"},{b:"prentice", ch:"Neuromuscular electrical stimulation"}],
  keywords:"faradic current effects tetanic contraction muscle pump re-education tendon transfer faradism under pressure faradic foot bath",
  mcq:[["Faradic current fails to stimulate denervated muscle because:",["Its frequency is too low","It is direct current","Its pulse duration is too short","It heats the tissue"],2,"Denervated muscle needs pulses of about 100 ms or longer."],["Faradic foot bath is mainly used for:",["Weak intrinsic muscles in flat foot","Hyperhidrosis","Plantar warts","Peripheral neuropathy"],0,"It strengthens the intrinsic muscles that support the longitudinal arch."]]
},
{
  id:"el-motor-points-preparation", title:"Motor points, apparatus testing and patient preparation for electrical stimulation", subject:"Electrotherapy", region:"Nerve and muscle", stages:"steps",
  aliases:["motor point","motor point chart","testing the apparatus","patient preparation electrotherapy","skin resistance","electrode placement","sensation testing"],
  simple:"A motor point is the spot on the skin where a muscle contracts with the least current, usually where its nerve enters the muscle. Before treatment, the therapist checks the machine works safely and prepares the patient: explanation, sensation test, clean moist skin and good electrode contact.",
  flow:["Explain the treatment and get consent","Check contraindications and test skin sensation","Test the apparatus on yourself, intensity at zero","Clean skin and moisten pads to cut resistance","Find motor point: lowest current, best contraction","Increase intensity slowly and monitor the skin"],
  exam:[
    {h:"Motor point: definition", p:["The point on the skin over a muscle at which a visible contraction is produced with the minimum current; it overlies the area where the motor nerve enters the muscle.","Usually at the junction of the upper third and lower two-thirds of the muscle belly (proximal part of the fleshy belly), but varies between people.","Denervated muscle has no motor point; stimulate the muscle belly instead."]},
    {h:"Common motor points", p:["Upper limb: deltoid (anterior, middle and posterior fibres, about 2-3 cm below the acromion), biceps (middle of the belly), triceps, wrist extensors (about 4 finger-breadths below the lateral epicondyle), thenar muscles.","Lower limb: vastus medialis (about 3-4 finger-breadths above the upper medial patella), rectus femoris, vastus lateralis, tibialis anterior (upper third lateral to the tibial crest), peronei, gastrocnemius heads.","Face: frontalis, orbicularis oculi, zygomaticus, orbicularis oris (Bell's palsy).","Nerve trunks: femoral nerve in the femoral triangle, common peroneal at the fibular neck, ulnar at the elbow, median at the wrist."]},
    {h:"Testing the apparatus", p:["Check mains lead, plug, earth, switches, leads and electrodes for damage; check the output controls start at zero.","Check the selected current, pulse duration, frequency and surge settings.","Test on the therapist's own forearm or thenar eminence: feel the current and see a contraction, confirming the circuit and polarity.","Check pads and sponges are clean and evenly wet; carbon rubber electrodes should not be cracked."]},
    {h:"Patient preparation", p:["Explain the sensation (tingling, contraction) and purpose; obtain consent.","Screen contraindications; test superficial sensation (sharp and blunt, sometimes hot and cold) and inspect skin.","Remove metal from the area; position comfortably with the muscle in a relaxed, supported, slightly lengthened position and the area exposed.","Reduce skin resistance: wash with soap and water or warm water, remove grease; avoid shaving just before (micro-cuts); moisten pads with tap water or saline; cover small cuts with petroleum jelly.","Secure electrodes with straps or tape for even contact; indifferent electrode larger and proximal, active electrode on the motor point."]},
    {h:"During and after treatment", p:["Increase intensity slowly while watching the contraction and the patient's face; ask about discomfort.","Check the skin under electrodes during and after; note erythema, blisters or burns.","Turn intensity to zero before removing electrodes; record parameters, number of contractions and response."]},
    {h:"Conclusion", p:["Accurate motor point placement and careful preparation of machine and patient give a strong, comfortable contraction with the least current and prevent shocks and burns."]}
  ],
  tip:"Draw an outline of the anterior thigh and leg with dots for motor points of rectus femoris, vastus medialis, vastus lateralis and tibialis anterior, and the femoral nerve in the femoral triangle. Add a box listing the order: explain, screen, test machine, prepare skin, place electrodes, increase slowly.",
  evidence:[["Electrode placement over motor points","Stronger contraction at lower current than random placement","Moderate (laboratory studies)"],["Skin preparation to lower impedance","More comfortable, even stimulation","Expert consensus"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy; Robertson et al., Electrotherapy Explained",
  outcomes:[["Sensation test record","Safe to stimulate"],["Current needed for minimal contraction","Excitability and placement accuracy"]],
  recent:["Motor point mapping studies with pen electrodes show motor points vary between individuals, supporting hunting for the best point rather than relying only on charts."],
  mnemonic:{word:"PREPARE", items:[["P","Purpose explained"],["R","Rule out contraindications"],["E","Examine sensation and skin"],["P","Plug, leads and output checked on yourself"],["A","Area cleaned and pads moistened"],["R","Relaxed, supported position"],["E","Electrodes secured, intensity up slowly"]], extra:"Motor point: junction of upper third and lower two-thirds of the belly."},
  example:"In a Salem district hospital, a student locates the vastus medialis motor point with a pen electrode before quadriceps stimulation, after washing the skin and testing sensation with a pin.",
  flags:["Absent sensation under the electrode area","Broken skin or rash under electrodes","Damaged leads or cracked electrodes","Intensity not at zero before switching on"],
  viva:[["What is a motor point?","The point where the least current produces a visible contraction, where the motor nerve enters the muscle."],["Why is the apparatus tested on the therapist?","To confirm the machine and leads work and the current is as expected before applying to the patient."],["How is skin resistance reduced?","Washing to remove grease and dead cells, warmth, and well-moistened pads with even contact."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: Motor points; Preparation of the patient."},{b:"cameron", ch:"Electrical currents: clinical application"},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Applying electrical stimulation."}],
  keywords:"motor point chart apparatus testing patient preparation skin resistance electrode placement sensation test",
  mcq:[["The motor point of a muscle usually lies:",["At the tendon insertion","At the musculotendinous junction distally","Over the bony origin","Where the motor nerve enters the muscle"],3,"It overlies the nerve entry point, often at the junction of upper third and lower two-thirds of the belly."],["Which step reduces skin resistance before stimulation?",["Shaving just before treatment","Washing the skin and moistening pads","Applying dry pads","Using smaller electrodes"],1,"Clean, moist skin with well-wetted pads lowers resistance; shaving just before causes micro-cuts."]]
},
{
  id:"el-idc-pulse-parameters", title:"Interrupted direct current: pulse duration, shape, frequency and production", subject:"Electrotherapy", region:"Denervated muscle", stages:"steps",
  aliases:["IDC","interrupted galvanic current","IGC pulses","rectangular pulse","triangular pulse","trapezoidal pulse","saw-tooth pulse"],
  simple:"Interrupted direct current is direct current switched on and off to make pulses. Long pulses (about 100 ms or more) are needed to make denervated muscle contract. The shape of the pulse matters: slowly rising pulses let healthy nerves ignore the current, so only the denervated muscle responds.",
  flow:["Direct current chopped into pulses","Pulse duration 0.01-300 ms; long for denervated muscle","Rectangular pulses rise instantly","Triangular or trapezoidal pulses rise slowly","Pulse rate low, with rest between pulses","Produced by electronic timing and switching circuits"],
  exam:[
    {h:"Definition", p:["Interrupted direct current (IDC, interrupted galvanic current) is a unidirectional current that flows for a set time (pulse) and is then stopped for a set interval, repeated regularly.","Used for electrodiagnosis (SD curve) and to stimulate denervated muscle."]},
    {h:"Pulse duration", p:["Range available on most stimulators: about 0.01 ms to 300 ms (or more).","Short pulses (0.1-1 ms) stimulate motor nerves of innervated muscle (faradic-type).","Long pulses (about 100-300 ms, sometimes 30-600 ms) are needed for denervated muscle, which has a long chronaxie; the duration is chosen as the shortest that gives a good contraction at tolerable intensity."]},
    {h:"Pulse shapes", p:["Rectangular (square): instant rise and fall; stimulates both nerve and muscle, used for SD curves and short-pulse stimulation.","Trapezoidal: slow rise, plateau, slow fall; gives smoother contraction.","Triangular and saw-tooth: slowly rising; normal nerve accommodates and does not fire, while denervated muscle (which accommodates poorly) contracts: selective stimulation.","Accommodation ratio can be tested by comparing thresholds for rectangular and slow-rising pulses."]},
    {h:"Frequency and interval", p:["Frequency refers to pulses per second (or per minute for long pulses); with 100 ms pulses, typically about 30 pulses per minute.","Interval between pulses at least 2-3 times the pulse duration (e.g. 100 ms pulse, 2-3 s rest) because denervated muscle fatigues quickly and must relax fully.","Each pulse gives a single slow (worm-like) contraction; no tetanus with long pulses."]},
    {h:"Production", p:["Older machines: mains rectified and smoothed by valves or diodes, interrupted by a motor-driven or metronome interrupter.","Modern machines: battery or mains power supply, low-voltage DC, an electronic timing circuit (multivibrator or microprocessor) and transistor switching to set pulse duration and interval; an output potentiometer controls intensity.","Constant-current output keeps current steady despite changing skin resistance; a polarity switch allows cathode or anode as active electrode."]},
    {h:"Dangers and precautions", p:["Chemical burns because current is unidirectional: use thick, well-soaked pads, low current density and check skin.","Electric shock with faulty equipment; general contraindications as for electrical stimulation."]},
    {h:"Conclusion", p:["Choosing a long pulse duration with a slow-rising shape and adequate rest interval lets IDC exercise denervated muscle selectively and safely."]}
  ],
  tip:"Draw four pulse shapes side by side (rectangular, trapezoidal, triangular, saw-tooth) on one time axis, label pulse duration and interval, and write 'normal nerve accommodates' under the slow-rising shapes.",
  evidence:[["Long-pulse stimulation of denervated muscle","Reduces atrophy in animal and some human studies","Low"],["Triangular pulses for selective stimulation","Allows denervated muscle response with less discomfort","Established physiology"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy; Robertson et al., Electrotherapy Explained",
  outcomes:[["SD curve and chronaxie","Degree of denervation and recovery"],["Visible contraction quality","Response to long pulses"]],
  recent:["Studies from Vienna (Kern and colleagues) on long-term denervated muscle in SCI showed home stimulation with very long, high-intensity pulses could restore muscle mass, renewing interest in denervated muscle stimulation."],
  mnemonic:{word:"LSR", items:[["L","Long pulse: 100-300 ms"],["S","Slow rise: triangular for selectivity"],["R","Rest: 2-3 s between pulses"]], extra:"Unidirectional means chemical burn risk: thick wet pads."},
  example:"A 19-year-old in Vellore with a radial nerve injury after a humerus fracture receives triangular 100 ms pulses to the wrist extensors; the forearm flexors stay relaxed while the denervated extensors contract slowly.",
  flags:["Chemical burns under electrodes","Impaired sensation over the denervated area: check skin often","Overfatigue of denervated muscle with short rest intervals"],
  viva:[["Why use triangular pulses for denervated muscle?","Normal nerve accommodates to slow rise and does not fire, but denervated muscle contracts."],["What pulse duration is used for denervated muscle?","About 100-300 ms."],["Why is the rest interval long?","Denervated muscle fatigues quickly and must relax fully between contractions."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Interrupted direct current."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Stimulation of denervated muscle."},{c:"Kern H, Carraro U, Adami N, et al. Home-based functional electrical stimulation rescues permanently denervated muscles in paraplegic patients with complete lower motor neuron lesion. Neurorehabil Neural Repair. 2010;24:709-721.", q:"Kern home-based functional electrical stimulation permanently denervated muscles paraplegic"}],
  keywords:"interrupted direct current IDC pulse duration rectangular triangular trapezoidal saw-tooth accommodation production denervated muscle",
  mcq:[["Which pulse shape allows selective stimulation of denervated muscle?",["Triangular","Rectangular","Biphasic square","Sinusoidal 50 Hz"],0,"Slowly rising pulses are ignored by accommodating normal nerve."],["A typical pulse duration to stimulate denervated muscle is:",["0.05 ms","0.5 ms","100 ms","10 s"],2,"Denervated muscle needs long pulses of about 100 ms or more."]]
},
{
  id:"el-igc-technique", title:"Technique of interrupted galvanic current (IGC) application", subject:"Electrotherapy", region:"Denervated muscle", stages:"steps",
  aliases:["IGC technique","IDC application","stable electrode technique","labile technique","denervated muscle stimulation technique","Bell's palsy stimulation"],
  simple:"To apply interrupted galvanic current, the therapist prepares the patient and skin, places an indifferent pad proximally and an active electrode over the denervated muscle belly, and gives slow contractions with long rests. The patient tries to help each contraction. Skin is checked often because galvanic current can burn.",
  flow:["Screen, explain and test sensation","Prepare skin; soak pads thickly","Indifferent pad proximal, active over muscle belly","Set long pulse, slow rise, 2-3 s rest","Increase intensity to slow visible contraction","Give sets, avoid fatigue, inspect skin after"],
  exam:[
    {h:"Indications", p:["Denervated or partially denervated muscle after peripheral nerve injury: Bell's palsy, radial nerve palsy, common peroneal nerve palsy, brachial plexus injury.","Aims: maintain muscle bulk and contractile properties, reduce fibrosis and oedema, retain awareness of the movement until reinnervation; also used in electrodiagnosis."]},
    {h:"Preparation", p:["Explain the procedure; check contraindications; test sensation (often reduced over the denervated area, so extra care).","Position: muscle relaxed, supported and in a slightly shortened or neutral position; the joint supported so it can move freely.","Wash skin; soak lint or sponge pads (about 1 cm thick, many layers) in tap water or saline; cover small cuts with petroleum jelly.","Test the apparatus on yourself."]},
    {h:"Electrode techniques", p:["Monopolar (unipolar): large indifferent electrode over the nerve root or proximal area (e.g. back of the neck or upper arm), small active electrode (usually cathode) over the muscle.","Bipolar: two equal electrodes over the proximal and distal ends of the muscle belly; used for large muscles or when monopolar gives poor response.","Stable technique: active electrode strapped in place for the whole treatment.","Labile technique: a pen or disc electrode moved over the belly to find the best point; often used for facial muscles in Bell's palsy."]},
    {h:"Parameters and dosage", p:["Pulse duration about 100-300 ms (shortest that gives a good contraction), triangular or trapezoidal pulse for selectivity.","Interval 2-3 s or more (about 20-30 pulses per minute).","Intensity: enough for a visible, slow contraction; usually higher than for innervated muscle.","Dose: about 3 sets of 10-30 contractions per muscle with rests between sets, once to several times daily (home units allow repeated sessions); stop at first sign of fatigue (weaker contraction)."]},
    {h:"During and after treatment", p:["Ask the patient to try to contract with each pulse to retain the motor pattern.","Watch the skin for redness or blistering; turn intensity down slowly to zero before removing electrodes.","Inspect skin, record parameters and response; repeat SD curve every 2-3 weeks to monitor reinnervation and reduce pulse duration as recovery occurs."]},
    {h:"Dangers and contraindications", p:["Chemical burns (alkaline under cathode, acid under anode), electric shock, fatigue.","Contraindications: pacemaker, anterior neck, malignancy, DVT, broken skin, poor sensation without careful monitoring, unreliable patient; in acute Bell's palsy some clinicians avoid stimulation because of possible synkinesis (evidence limited)."]},
    {h:"Conclusion", p:["Careful electrode technique, long pulses with rest, and close skin monitoring make IGC a safe adjunct to splinting and re-education while waiting for reinnervation."]}
  ],
  tip:"Draw a forearm with a large indifferent pad on the upper arm and a small active electrode over the wrist extensor belly (monopolar), and beside it two equal pads at either end of the belly (bipolar). Note stable versus labile.",
  evidence:[["Electrical stimulation for Bell's palsy","No clear benefit in trials; possible harm debated","Low"],["Stimulation of denervated muscle in peripheral nerve injury","May slow atrophy; recovery benefit uncertain","Low"]],
  evidenceSource:"Cochrane review of physical therapy for Bell's palsy (Teixeira et al.); Forster and Palastanga, Clayton's Electrotherapy",
  outcomes:[["House-Brackmann grade","Facial nerve recovery"],["SD curve, chronaxie","Progress of reinnervation"],["MMT","Return of voluntary power"]],
  recent:["A Cochrane review of physical therapy for Bell's palsy (Teixeira et al., 2011) found low-quality evidence and no clear benefit from electrical stimulation."],
  mnemonic:{word:"SLOW", items:[["S","Selective triangular pulses"],["L","Long pulse 100-300 ms"],["O","One contraction every 2-3 s"],["W","Watch the skin for burns"]], extra:"Active electrode: usually the cathode over the belly."},
  example:"A 35-year-old woman in Kanchipuram with a complete common peroneal nerve palsy after a fibular neck fracture receives IGC to tibialis anterior with a labile pen electrode while wearing a foot drop splint between sessions.",
  flags:["Chemical burns, especially with poor sensation","Fatigue of denervated muscle","Stimulation over anterior neck or near pacemaker","Synkinesis concerns in acute Bell's palsy"],
  viva:[["What is the labile technique?","The active electrode is moved over the muscle during treatment, rather than fixed."],["Why test the SD curve during treatment?","To track reinnervation and shorten pulse duration as the muscle recovers."],["What is the main danger of IGC?","Chemical burns under the electrodes."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Stimulation of denervated muscle."},{b:"cameron", ch:"Electrical currents for muscle contraction"},{c:"Teixeira LJ, Valbuza JS, Prado GF. Physical therapy for Bell's palsy (idiopathic facial paralysis). Cochrane Database Syst Rev. 2011.", q:"Teixeira physical therapy Bell's palsy Cochrane"}],
  keywords:"IGC technique interrupted galvanic denervated muscle monopolar bipolar stable labile Bell's palsy peroneal nerve palsy",
  mcq:[["In the labile technique the active electrode is:",["Fixed with a strap","Moved over the muscle during treatment","Placed on the opposite limb","Placed over the spine only"],1,"Labile means moving; stable means fixed."],["How often are contractions given with IGC for denervated muscle?",["50 per second","One per minute only","Continuous for 20 minutes","About one every 2-3 seconds"],3,"Long rest intervals of about 2-3 s prevent fatigue."]]
},
{
  id:"el-current-selection", title:"Selection of current: parameters for stimulating nerve and muscle", subject:"Electrotherapy", region:"Nerve and muscle", stages:"steps",
  aliases:["selection of current","stimulation parameters","NMES parameters","pulse duration frequency intensity","duty cycle","choice of current for innervated and denervated muscle"],
  simple:"The right current depends on what you want to stimulate. Sensory nerves for pain need short pulses at high frequency; motor nerves for contraction need slightly longer pulses at 30-50 Hz; denervated muscle needs very long pulses. Ramp, on and off times and intensity are then set for comfort and fatigue.",
  flow:["Decide the target: sensory nerve, motor nerve or muscle","Set pulse duration from the SD relationship","Set frequency: twitch, tetanus or pain relief","Set ramp, on and off times (duty cycle)","Adjust intensity to the needed response","Review fatigue, comfort and progress"],
  exam:[
    {h:"Principle", p:["Nerve and muscle each have a strength-duration relationship; shorter pulses need more intensity.","Large sensory (A-beta) fibres have the lowest threshold, then motor (A-alpha) fibres, then pain fibres (A-delta, C); denervated muscle fibres have a very high threshold and long chronaxie.","So pulse duration and intensity choose which tissue responds, and frequency decides the type of response."]},
    {h:"Pulse duration", p:["Sensory stimulation (TENS): about 50-100 microseconds (up to 200).","Motor nerve stimulation of innervated muscle: about 200-400 microseconds (0.1-1 ms with older faradic units); larger muscles such as quadriceps often 300-400 microseconds.","Denervated muscle: about 100-300 ms (and longer in long-standing denervation)."]},
    {h:"Frequency", p:["1-10 Hz: individual twitches; used for acupuncture-like TENS, muscle pumping and endorphin release.","20-30 Hz: smooth (fused) tetanic contraction begins; 30-50 Hz for strengthening and FES with less fatigue than higher rates.","50-100 Hz: strong tetanic contraction (faradic) but faster fatigue.","80-150 Hz: sensory stimulation for pain gating (conventional TENS, IFT AMF)."]},
    {h:"Waveform, ramp and duty cycle", p:["Biphasic symmetrical pulses for large muscles, asymmetrical balanced for small muscles; monophasic only when polarity is needed (HVPGS, iontophoresis is DC).","Ramp up 1-2 s and ramp down 1 s for comfort and to mimic voluntary contraction (shorter ramp for FES timing).","On:off ratio: 1:5 initially (e.g. 10 s on, 50 s off) for strengthening; progress to 1:3 or 1:1 for endurance as fatigue allows.","Medium frequency options: Russian 2500 Hz burst at 50 Hz, IFC 4000 Hz with chosen AMF."]},
    {h:"Intensity and dosage", p:["Sensory: strong but comfortable tingling without contraction.","Motor re-education: visible contraction, comfortable.","Strengthening: as high as tolerated, ideally at least 50 percent of maximal voluntary isometric contraction; 10-20 contractions per session, 3-5 days a week.","Denervated: slow visible contraction; 3 sets of 10-30, avoid fatigue."]},
    {h:"Summary table (write as a table in exam)", p:["Pain (conventional TENS): 50-100 microseconds, 80-150 Hz, sensory level, 30-60 min or longer.","Re-education (innervated): 200-400 microseconds, 30-50 Hz, ramp 1-2 s, 1:3 to 1:5, visible contraction.","Strengthening (NMES or Russian): 300-400 microseconds or 2500 Hz burst, 50 Hz, 10 s on 50 s off, maximal tolerated.","Oedema (muscle pump): 1-10 Hz twitch or surged, limb elevated.","Denervated muscle: 100-300 ms triangular, one every 2-3 s."]},
    {h:"Conclusion", p:["Selecting current is a logical process: target tissue sets pulse duration, desired response sets frequency, and fatigue and comfort set ramp, duty cycle and intensity."]}
  ],
  tip:"Draw a strength-duration curve and mark three zones on the duration axis: short pulses (sensory and motor nerve), and long pulses (denervated muscle). Add a small table of goal, pulse duration, frequency and on:off.",
  evidence:[["High-intensity NMES for quadriceps strength","Strength gains related to training intensity","Moderate"],["Lower frequencies (30-50 Hz) vs higher for fatigue","Less fatigue at lower frequency","Moderate (laboratory)"]],
  evidenceSource:"Cameron, Physical Agents in Rehabilitation; Robertson et al., Electrotherapy Explained",
  outcomes:[["Dynamometry (% MVIC)","Training intensity and strength gain"],["NPRS","Pain relief with sensory stimulation"],["Contraction quality and fatigue","Correct parameter choice"]],
  recent:["Clinical guidance on NMES increasingly stresses training intensity (percentage of maximal voluntary contraction) as the main driver of strength gains, more than waveform brand."],
  mnemonic:{word:"PFRI", items:[["P","Pulse duration picks the tissue"],["F","Frequency picks the response"],["R","Ramp and rest manage comfort and fatigue"],["I","Intensity sets the dose"]], extra:"Sensory under 100 microseconds, motor 200-400 microseconds, denervated 100-300 ms."},
  example:"A student in Madurai designs three settings on one stimulator: 100 Hz, 80 microseconds for knee OA pain; 35 Hz, 300 microseconds, 10 s on 30 s off for quadriceps re-education; and 100 ms triangular pulses for a denervated tibialis anterior.",
  flags:["Excessive intensity causing muscle damage or fracture in osteoporotic bone","Fatigue from high frequency or short rest","General electrical stimulation contraindications"],
  viva:[["What frequency gives a fused tetanic contraction?","About 20-30 Hz and above."],["What on:off ratio starts NMES strengthening?","About 1:5, e.g. 10 s on, 50 s off."],["Which fibres are recruited first as intensity rises?","Large sensory A-beta fibres, then motor fibres, then pain fibres."]],
  refs:[{b:"cameron", ch:"Electrical currents for muscle contraction"},{b:"prentice", ch:"Basic principles of electricity and electrical stimulating currents"},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Electrical stimulation parameters."}],
  keywords:"selection of current stimulation parameters pulse duration frequency ramp duty cycle on off ratio intensity NMES sensory motor denervated",
  mcq:[["Which pulse duration suits stimulation of denervated muscle?",["50 microseconds","300 microseconds","100 ms","1 ms"],2,"Denervated muscle needs long pulses of around 100 ms or more."],["For NMES strengthening, a starting on:off ratio is about:",["1:5","5:1","1:1","Continuous on"],0,"Long rest (10 s on, 50 s off) limits fatigue early in training."]]
},
{
  id:"el-emg", title:"Electromyography (EMG): electrodes, signal, amplifiers and wave patterns", subject:"Electrotherapy", region:"Nerve and muscle", stages:"steps",
  aliases:["EMG","electromyography","needle EMG","surface EMG","MUAP","fibrillation potentials","positive sharp waves","interference pattern"],
  simple:"EMG records the electrical activity of muscle. Electrodes pick up tiny signals, amplifiers enlarge them and the screen and speaker show the waves. A healthy muscle is silent at rest; denervated muscle shows spontaneous fibrillations, and nerve or muscle disease changes the size and shape of motor unit potentials.",
  flow:["Electrodes pick up muscle electrical activity","Differential amplifier rejects noise, enlarges signal","Filters and display show waves; speaker gives sound","Rest: normal muscle is electrically silent","Contraction: motor unit potentials and recruitment","Patterns distinguish neuropathy from myopathy"],
  exam:[
    {h:"Definition", p:["Electromyography is the recording and study of electrical activity from muscle at rest and during voluntary contraction, used to diagnose lower motor neuron, neuromuscular junction and muscle disorders, and in kinesiology and biofeedback."]},
    {h:"Electrodes", p:["Surface electrodes: silver-silver chloride discs on the skin; non-invasive; record overall activity of superficial muscles; used in kinesiology, gait analysis and biofeedback.","Needle electrodes: concentric needle (core and shaft), monopolar needle (with a separate reference), single fibre needle; record individual motor unit potentials from deep muscles; used in clinical diagnosis.","Ground (earth) electrode reduces interference; fine-wire electrodes for deep muscles in research."]},
    {h:"Signal and instrumentation", p:["Signal is small: microvolts to a few millivolts; frequency content roughly 10-500 Hz (surface) and up to several kHz (needle).","Differential amplifier: amplifies the difference between two inputs and rejects signals common to both (mains hum); high common mode rejection ratio (about 90-100 dB or more) and high input impedance needed.","Filters: band-pass filters remove movement artefact (low end) and noise (high end); a 50 Hz notch filter for mains in India.","Display on screen and loudspeaker (each pattern has a typical sound); processing: rectification, smoothing, integration and RMS for amplitude, frequency analysis for fatigue."]},
    {h:"Normal findings", p:["Insertional activity: brief burst on needle movement that stops quickly.","At rest: electrical silence (apart from end-plate noise near motor points).","Mild contraction: motor unit action potentials (MUAPs), bi- or triphasic, amplitude about 0.2-2 mV (up to about 3 mV), duration about 5-15 ms.","Maximal contraction: full interference pattern; baseline obscured by overlapping MUAPs."]},
    {h:"Abnormal wave patterns", p:["Denervation (LMN lesion): increased insertional activity, fibrillation potentials and positive sharp waves at rest, appearing about 2-3 weeks after injury; reduced recruitment.","Chronic neuropathy and reinnervation: large amplitude, long duration, polyphasic MUAPs; reduced (discrete) interference pattern; fasciculations (e.g. motor neuron disease).","Myopathy: small amplitude, short duration, polyphasic MUAPs; early recruitment with a full interference pattern despite weakness.","Myotonic discharges: waxing and waning (dive-bomber sound) in myotonic dystrophy and myotonia congenita; complex repetitive discharges in chronic conditions."]},
    {h:"Physiotherapy relevance", p:["Helps confirm and localise nerve lesions (with NCS), detect early reinnervation (nascent units) before visible movement, and plan stimulation and re-education.","Surface EMG used in gait and posture analysis, fatigue studies, ergonomics and EMG biofeedback."]},
    {h:"Conclusion", p:["EMG adds information about the state of muscle and its nerve supply; physiotherapists mainly use surface EMG for assessment and biofeedback, while needle EMG is a specialist diagnostic test."]}
  ],
  tip:"Draw a block diagram: electrodes, differential amplifier, filter, display and speaker. Under it draw three traces: normal triphasic MUAP, neurogenic (tall, wide, polyphasic) and myopathic (small, short, polyphasic), and a small fibrillation potential and positive sharp wave.",
  evidence:[["Needle EMG for diagnosing denervation","Detects denervation potentials after about 2-3 weeks","Established diagnostic practice"],["Surface EMG for clinical diagnosis of neuromuscular disease","Limited diagnostic value compared with needle EMG","Moderate"]],
  evidenceSource:"Kimura, Electrodiagnosis in Diseases of Nerve and Muscle; Robertson et al., Electrotherapy Explained",
  outcomes:[["Fibrillations and positive sharp waves","Active denervation"],["MUAP size and recruitment","Neurogenic vs myopathic change"],["Nascent MUAPs","Early reinnervation"]],
  recent:["High-density surface EMG using electrode grids is increasingly used in research to study motor unit behaviour non-invasively."],
  mnemonic:{word:"BIG vs SMALL", items:[["BIG","Neurogenic: big, long, polyphasic, reduced recruitment"],["SMALL","Myopathic: small, short, polyphasic, early recruitment"],["Fibs","Denervation at rest after 2-3 weeks"]], extra:"Normal muscle at rest is silent."},
  example:"Three weeks after a deep cut at the wrist, a 26-year-old in Chennai has needle EMG of the abductor pollicis brevis showing fibrillations and positive sharp waves, confirming median nerve denervation.",
  flags:["Bleeding risk with needle EMG in patients on anticoagulants","Infection control for needle electrodes","Testing too early (under about 2-3 weeks) may miss denervation"],
  viva:[["What is seen at rest in normal muscle on EMG?","Electrical silence."],["When do fibrillation potentials appear after nerve injury?","About 2-3 weeks after denervation."],["Why use a differential amplifier?","To reject noise common to both electrodes, such as mains hum, and amplify the muscle signal."]],
  refs:[{c:"Kimura J. Electrodiagnosis in Diseases of Nerve and Muscle: Principles and Practice. Chapters: Electromyography; Types of abnormalities."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Electromyography and electrodiagnosis."},{b:"cameron", ch:"Electromyographic biofeedback"}],
  keywords:"EMG electromyography surface needle electrode differential amplifier CMRR MUAP fibrillation positive sharp wave interference pattern neuropathy myopathy",
  mcq:[["Small, short, polyphasic MUAPs with early recruitment suggest:",["Motor neuron disease","Normal muscle","Peripheral nerve injury","Myopathy"],3,"Myopathic units are small and short; many are recruited early."],["The function of a differential amplifier in EMG is to:",["Heat the electrode","Reject signals common to both inputs","Stimulate the nerve","Measure joint angle"],1,"High common mode rejection removes interference such as 50 Hz hum."]]
},
{
  id:"el-ncs-h-f", title:"Nerve conduction studies, H reflex and F wave", subject:"Electrotherapy", region:"Peripheral nerve", stages:"steps",
  aliases:["NCS","nerve conduction velocity","NCV","CMAP","SNAP","H reflex","F wave","distal latency"],
  simple:"Nerve conduction studies stimulate a nerve with short electric pulses and record how fast and how strongly the signal reaches a muscle or sensory site. Slowing points to damaged myelin; small responses point to lost axons. The H reflex and F wave test the proximal nerve and roots.",
  flow:["Stimulate nerve with supramaximal short pulses","Record CMAP from muscle or SNAP from nerve","Measure latency, amplitude and conduction velocity","Slowing or block suggests demyelination","Small amplitude suggests axonal loss","H reflex and F wave test proximal segments and roots"],
  exam:[
    {h:"Definition and principle", p:["NCS measure the speed and size of electrical conduction in peripheral nerves after percutaneous electrical stimulation, using surface stimulating and recording electrodes.","Stimulus: square pulse of about 0.1-0.2 ms (up to 1 ms), increased to supramaximal (about 20-25 percent above the level giving a maximal response) so all axons fire."]},
    {h:"Motor conduction", p:["Recording electrode over the motor point of a distal muscle (e.g. abductor pollicis brevis for median), reference over the tendon, ground between.","Stimulate at two sites (e.g. wrist and elbow); record compound muscle action potential (CMAP).","Measures: distal motor latency, CMAP amplitude, and conduction velocity = distance between sites / (proximal latency - distal latency).","Normal motor velocity: about 50-60 m/s or more in the upper limb, above about 40 m/s in the lower limb (laboratory norms vary; cooling slows conduction)."]},
    {h:"Sensory conduction", p:["Orthodromic (stimulate finger, record over nerve proximally) or antidromic (stimulate nerve, record over digit).","Sensory nerve action potential (SNAP): small (microvolts), measures latency, amplitude and velocity.","SNAP is preserved in lesions proximal to the dorsal root ganglion (radiculopathy, plexus avulsion) despite sensory loss: a key localising sign."]},
    {h:"Interpretation", p:["Demyelination: slowed velocity, prolonged distal latency, conduction block and temporal dispersion (e.g. GBS, CIDP, carpal tunnel at the wrist).","Axonal loss: reduced CMAP or SNAP amplitude with relatively normal velocity (e.g. diabetic or alcoholic polyneuropathy, nerve injury).","Neurapraxia: block across the lesion with normal conduction distal to it; axonotmesis: distal amplitude falls over about 7-10 days as Wallerian degeneration proceeds."]},
    {h:"H reflex", p:["Electrical equivalent of the ankle (Achilles) reflex: tibial nerve stimulated in the popliteal fossa with a submaximal, longer pulse (about 0.5-1 ms), recorded from soleus.","Afferent Ia fibres to the spinal cord, synapse on alpha motor neurons, efferent back to the muscle: monosynaptic reflex; latency about 28-35 ms (depends on height).","Absent or delayed in S1 radiculopathy, polyneuropathy and GBS; H/M ratio increased in spasticity (upper motor neuron lesions)."]},
    {h:"F wave", p:["Small late response after supramaximal stimulation of any motor nerve: antidromic impulse reaches anterior horn cells, a few backfire and send an orthodromic impulse to the muscle (no synapse).","Variable latency and shape; about 25-32 ms in the upper limb and 45-56 ms in the lower limb.","Prolonged or absent F waves are an early sign in GBS and help assess proximal segments and roots."]},
    {h:"Conclusion", p:["NCS, H reflex and F wave together localise a lesion along the nerve and separate demyelination from axonal loss, guiding prognosis and physiotherapy planning."]}
  ],
  tip:"Draw an arm with stimulating sites at wrist and elbow, a recording electrode on the thenar eminence, and two CMAP traces with latencies marked. Write the formula CV = distance / (L2 - L1). Add a spinal cord loop sketch showing H reflex (via synapse) and F wave (backfiring anterior horn cell).",
  evidence:[["NCS for carpal tunnel syndrome","Sensitive and specific diagnostic test, used to grade severity","Established diagnostic practice"],["F wave in early GBS","Often the earliest abnormality","Established diagnostic practice"]],
  evidenceSource:"Kimura, Electrodiagnosis in Diseases of Nerve and Muscle; AANEM educational guidance",
  outcomes:[["Conduction velocity","Myelin integrity"],["CMAP and SNAP amplitude","Number of conducting axons"],["H reflex latency and H/M ratio","S1 root and spinal excitability"]],
  recent:["Neuromuscular ultrasound is increasingly combined with NCS to show nerve swelling and entrapment sites, for example in carpal tunnel syndrome."],
  mnemonic:{word:"SLOW or SMALL", items:[["SLOW","Demyelination: slow velocity, long latency, block"],["SMALL","Axonal: small amplitude, near-normal speed"],["H","Hoffmann: S1, soleus, monosynaptic"],["F","First seen in GBS, backfiring, no synapse"]], extra:"SNAP spared in root lesions proximal to the DRG."},
  example:"A 45-year-old tailor in Tirupur with night numbness of the thumb and index finger has prolonged median distal motor and sensory latencies at the wrist, confirming carpal tunnel syndrome before splinting and nerve gliding.",
  flags:["Cardiac pacemaker or implanted defibrillator: specialist precautions","Cold limbs falsely slow conduction: warm to about 32 degrees C","Testing in the first week after injury can miss axonal loss"],
  viva:[["How is motor conduction velocity calculated?","Distance between two stimulation sites divided by the difference in latencies."],["What is the H reflex?","The electrically evoked monosynaptic stretch reflex, usually tibial nerve to soleus."],["How does the F wave differ from the H reflex?","F wave uses supramaximal stimulation and antidromic backfiring of motor neurons without a synapse; H reflex is a submaximal reflex through a synapse."]],
  refs:[{c:"Kimura J. Electrodiagnosis in Diseases of Nerve and Muscle: Principles and Practice. Chapters: Nerve conduction studies; The F wave; The H reflex."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Electrodiagnosis."},{b:"guyton", ch:"Motor functions of the spinal cord; the cord reflexes"}],
  keywords:"nerve conduction study NCV CMAP SNAP distal latency conduction velocity demyelination axonal H reflex F wave GBS carpal tunnel radiculopathy",
  mcq:[["Reduced CMAP amplitude with normal conduction velocity suggests:",["Axonal loss","Demyelination","Normal nerve","Myotonia"],0,"Axonal loss reduces the number of conducting fibres but surviving fibres conduct normally."],["The H reflex is usually recorded from:",["Abductor pollicis brevis","Tibialis anterior","Soleus","Biceps brachii"],2,"Tibial nerve stimulation in the popliteal fossa, recording from soleus."]]
},
{
  id:"el-biofeedback", title:"Biofeedback: principles and uses; EMG biofeedback", subject:"Electrotherapy", region:"Neuromuscular", stages:"steps",
  aliases:["biofeedback","EMG biofeedback","myofeedback","pressure biofeedback","feedback therapy","relaxation training","pelvic floor biofeedback"],
  simple:"Biofeedback turns a body signal the patient cannot easily feel, such as muscle activity, into a sound or a picture. Watching or hearing it helps the patient learn to increase activity in a weak muscle or reduce it in a tense or spastic one. EMG biofeedback uses surface electrodes to show muscle activity.",
  flow:["Sensor detects a body signal (EMG, pressure, angle)","Signal is amplified and processed","Shown as sound, light or graph to patient","Therapist sets a threshold target","Patient practises to reach or stay below target","Feedback is faded as control is learned"],
  exam:[
    {h:"Definition and principle", p:["Biofeedback is the use of instruments to detect and display physiological information (muscle activity, joint angle, pressure, heart rate, skin temperature) so the patient can learn voluntary control of it.","Based on operant conditioning and motor learning: immediate, accurate knowledge of performance reinforces correct responses."]},
    {h:"Types of biofeedback", p:["EMG (myoelectric) biofeedback: most used in physiotherapy.","Pressure biofeedback (e.g. inflatable cuff used for deep abdominal and neck flexor training), force plate or weight-bearing feedback, electrogoniometer (joint angle) feedback.","Heart rate, blood pressure, skin temperature, galvanic skin response (stress), respiratory and EEG (neurofeedback)."]},
    {h:"EMG biofeedback: instrumentation and method", p:["Three surface electrodes (two active over the muscle belly along fibre direction, one reference) after skin preparation.","Differential amplifier, filtering, full-wave rectification and smoothing or integration; output displayed as a bar, line graph, lights or tone whose pitch rises with activity.","Electrode spacing: close spacing records local, specific activity; wide spacing records a larger area (useful for relaxation).","Sensitivity (gain) set so target is achievable; threshold raised (up-training) or lowered (down-training) as performance improves."]},
    {h:"Clinical uses", p:["Up-training (increase activity): weak muscles after stroke (e.g. tibialis anterior, wrist extensors), quadriceps after knee surgery, VMO timing in patellofemoral pain, pelvic floor muscles in stress incontinence.","Down-training (relaxation): spastic muscles, tension-type headache (frontalis or upper trapezius), bruxism, chronic neck and back pain with guarding, anxiety.","Re-education after tendon transfer, posture training and work ergonomics."]},
    {h:"Treatment protocol", p:["Explain the signal; start in an easy position; sessions about 20-30 minutes with short trials (e.g. 10 s contraction, 10-20 s rest).","Set realistic thresholds; progress to functional positions and tasks; reduce feedback frequency (fading) to avoid dependence and promote retention."]},
    {h:"Advantages, limitations and precautions", p:["Advantages: safe, non-invasive, motivating, objective record of progress, patient active.","Limitations: needs cognition, attention and vision or hearing; surface EMG picks up cross-talk from neighbouring muscles; evidence often shows benefit only when added to standard therapy.","Precautions: skin allergy to electrode gel, broken skin; no current is applied, so there are no electrical stimulation contraindications."]},
    {h:"Conclusion", p:["Biofeedback gives patients a window into their own muscles; EMG biofeedback is a useful adjunct for up-training weak and down-training overactive muscles, with feedback faded as control improves."]}
  ],
  tip:"Draw a block diagram: patient muscle, surface electrodes, amplifier, rectifier and integrator, display (bar and tone), and an arrow back to the patient's brain labelled 'feedback loop'. Mark the threshold line on the display.",
  evidence:[["Biofeedback added to pelvic floor muscle training for incontinence in women","Some added benefit, may reflect extra contact time","Low-moderate"],["EMG biofeedback for motor recovery after stroke","Small, inconsistent benefits over standard therapy","Low"],["Biofeedback for tension-type headache","Reduces headache frequency","Moderate"]],
  evidenceSource:"Cochrane reviews by Herderschee et al. (2011) and Woodford and Price (2007); Cameron, Physical Agents in Rehabilitation",
  outcomes:[["Peak and mean EMG amplitude","Change in muscle activation"],["Pad test or bladder diary","Continence outcome"],["Fugl-Meyer assessment","Motor recovery after stroke"]],
  recent:["Wearable surface EMG sensors linked to mobile apps and games now allow home biofeedback practice, though trial evidence for these devices is still limited."],
  mnemonic:{word:"UP and DOWN", items:[["UP","Up-train weak muscle: raise threshold"],["DOWN","Down-train tense or spastic muscle: lower threshold"],["FADE","Fade feedback to build independence"]], extra:"Close electrodes = specific; wide electrodes = general."},
  example:"A 62-year-old retired bank officer in Bengaluru with stroke uses EMG biofeedback on his wrist extensors; a rising tone helps him find the contraction he could not feel, and he progresses to grasp and release tasks.",
  flags:["Poor cognition or attention limits use","Skin reaction to electrodes or gel","Cross-talk misleading the patient","Dependence on feedback if not faded"],
  viva:[["What is EMG biofeedback?","Recording surface EMG and converting it into visual or auditory signals so the patient can learn to control muscle activity."],["What is down-training?","Using feedback to reduce muscle activity, e.g. in spasticity or tension headache."],["Why is feedback faded?","To make the patient rely on internal cues and retain the skill."]],
  refs:[{b:"cameron", ch:"Electromyographic biofeedback"},{c:"Herderschee R, Hay-Smith EJC, Herbison GP, Roovers JP, Heineman MJ. Feedback or biofeedback to augment pelvic floor muscle training for urinary incontinence in women. Cochrane Database Syst Rev. 2011.", q:"Herderschee biofeedback pelvic floor muscle training urinary incontinence Cochrane"},{c:"Woodford H, Price C. EMG biofeedback for the recovery of motor function after stroke. Cochrane Database Syst Rev. 2007.", q:"Woodford Price EMG biofeedback motor function stroke Cochrane"}],
  keywords:"biofeedback EMG biofeedback surface electrode threshold up-training down-training pelvic floor stroke tension headache pressure biofeedback",
  mcq:[["In EMG biofeedback, down-training is used for:",["Weak tibialis anterior after stroke","Tension-type headache with overactive frontalis","Quadriceps inhibition","Pelvic floor weakness"],1,"Down-training lowers unwanted muscle activity."],["Biofeedback is mainly based on:",["Gate control theory","Piezoelectric effect","Electrolysis","Operant conditioning and motor learning"],3,"Immediate feedback reinforces correct responses."]]
},
{
  id:"el-gate-control-descending", title:"Gate control theory and descending pain suppression", subject:"Electrotherapy", region:"Nervous system", stages:"steps",
  aliases:["gate control theory","Melzack and Wall","pain gate","descending pain inhibition","endogenous opioids","PAG","substantia gelatinosa"],
  simple:"Gate control theory says the spinal cord has a 'gate' for pain: touch signals from large nerve fibres can close it, while pain fibres open it. The brain can also send signals down the spinal cord to block pain, using natural opioids, serotonin and noradrenaline. TENS and IFT use both ideas.",
  flow:["Pain signals travel in thin A-delta and C fibres","Large A-beta touch fibres also reach the dorsal horn","Substantia gelatinosa interneurons inhibit transmission (T) cells","A-beta input closes the gate; C input opens it","Brain (PAG, raphe) sends descending inhibition","Opioids, serotonin, noradrenaline reduce dorsal horn firing"],
  exam:[
    {h:"Introduction", p:["Proposed by Melzack and Wall in 1965 (Science) to explain why rubbing a painful area or psychological state changes pain.","Provides the main rationale for conventional TENS, IFT and counter-irritants."]},
    {h:"Components of the gate", p:["Large-diameter myelinated A-beta fibres (touch, vibration).","Small-diameter A-delta (sharp pain) and unmyelinated C fibres (dull, burning pain).","Substantia gelatinosa (lamina II) inhibitory interneurons (SG cells).","Transmission cells (T cells, projection neurons, e.g. lamina V wide dynamic range cells) that send pain to the brain via the spinothalamic tract."]},
    {h:"Mechanism", p:["A-beta input excites SG cells, which inhibit T cells presynaptically: the gate closes and less pain is transmitted.","A-delta and C input inhibits SG cells, so the gate opens and T cells fire.","Pain felt depends on the balance of large and small fibre activity plus central control from the brain (attention, emotion, past experience).","Application: conventional TENS (high frequency, short pulse, sensory level) selectively activates A-beta fibres to close the gate; rubbing, vibration and massage do the same."]},
    {h:"Descending pain suppression", p:["Periaqueductal grey (PAG) in the midbrain is activated by higher centres and by opioids.","PAG projects to the rostral ventromedial medulla (nucleus raphe magnus), which sends serotonergic fibres down the dorsolateral funiculus to the dorsal horn; locus coeruleus sends noradrenergic fibres.","In the dorsal horn these activate enkephalin interneurons, which inhibit pain transmission pre- and postsynaptically.","Endogenous opioids: beta-endorphin, enkephalins and dynorphins act on mu, delta and kappa receptors.","Diffuse noxious inhibitory control (conditioned pain modulation): a painful stimulus in one area reduces pain elsewhere."]},
    {h:"Application to electrotherapy", p:["Conventional TENS (80-150 Hz, 50-100 microseconds, comfortable tingling): mainly segmental gate control; fast onset, short carry-over.","Acupuncture-like TENS (2-4 Hz, 100-300 microseconds, visible twitch) and low AMF IFT: descending inhibition and endorphin release; slower onset, longer relief; animal work shows low-frequency TENS effects depend on mu-opioid receptors and high-frequency on delta-opioid receptors.","Brief intense TENS: counter-irritation with near-maximal tolerated stimulation, for short painful procedures."]},
    {h:"Limitations", p:["The original circuit has been revised; details of SG cell action are more complex than first proposed.","Does not explain chronic pain fully; central sensitisation and the brain's role (neuromatrix theory by Melzack) are now emphasised."]},
    {h:"Conclusion", p:["Gate control and descending inhibition explain how sensory stimulation and the brain itself can turn pain down, and they underpin TENS dosing; modern pain science adds central sensitisation and psychosocial factors."]}
  ],
  tip:"Draw the classic gate diagram: A-beta (L) and C (S) fibres entering the dorsal horn, SG interneuron with plus and minus signs to the T cell, T cell going up to the brain, and a descending arrow from PAG and raphe magnus to the dorsal horn labelled serotonin and enkephalin.",
  evidence:[["Conventional TENS for acute pain","Reduces pain during use","Moderate"],["Low-frequency TENS analgesia reversed by naloxone in animal studies","Supports opioid-mediated descending mechanism","Moderate (laboratory)"]],
  evidenceSource:"Melzack and Wall, Science 1965; Sluka and Walsh, J Pain 2003; Robertson et al., Electrotherapy Explained",
  outcomes:[["NPRS or VAS","Pain intensity"],["Pressure pain threshold (algometer)","Local and widespread hypoalgesia"],["Conditioned pain modulation tests","Efficiency of descending inhibition"]],
  recent:["Research shows people with fibromyalgia and some chronic pain conditions often have reduced descending inhibition, and regular opioid users may respond less to low-frequency TENS (Sluka group)."],
  mnemonic:{word:"Large closes, Small opens", items:[["L","A-beta closes the gate"],["S","A-delta and C open the gate"],["PAG","Brain sends opioids and serotonin down"]], extra:"High frequency TENS = gate; low frequency TENS = endorphins."},
  example:"After a fall from his bike in Hyderabad, a 20-year-old student rubs his bruised shin and feels less pain: large touch fibres closing the gate, the same principle as conventional TENS.",
  flags:["Persistent unexplained pain needs medical review, not just gating","Chronic pain with central sensitisation may not respond to peripheral stimulation alone"],
  viva:[["Who proposed gate control theory and when?","Melzack and Wall, 1965."],["Where is the gate located?","In the substantia gelatinosa of the dorsal horn of the spinal cord."],["Which neurotransmitter descends from the nucleus raphe magnus?","Serotonin (5-HT)."]],
  refs:[{c:"Melzack R, Wall PD. Pain mechanisms: a new theory. Science. 1965;150:971-979.", q:"Melzack Wall pain mechanisms new theory 1965"},{c:"Sluka KA, Walsh D. Transcutaneous electrical nerve stimulation: basic science mechanisms and clinical effectiveness. J Pain. 2003;4:109-121.", q:"Sluka Walsh TENS basic science mechanisms clinical effectiveness"},{b:"guyton", ch:"Somatic sensations: pain, headache and thermal sensations"}],
  keywords:"gate control theory Melzack Wall substantia gelatinosa A-beta C fibre descending inhibition PAG raphe magnus endorphins enkephalin TENS",
  mcq:[["According to gate control theory, the gate is closed by:",["C fibre activity","Sympathetic fibres","A-beta fibre activity","Gamma motor neurons"],2,"Large A-beta input excites SG interneurons, which inhibit T cells."],["The midbrain centre that starts descending pain inhibition is:",["Periaqueductal grey","Red nucleus","Substantia nigra","Superior colliculus"],0,"PAG activates the raphe magnus and descending serotonergic pathways."]]
},
{
  id:"el-tens-placement-uses", title:"TENS: electrode placement, uses and contraindications", subject:"Electrotherapy", region:"Peripheral nerve and painful area", stages:"steps",
  aliases:["TENS electrode placement","dermatomal placement","TENS in labour","TENS uses","TENS contraindications","acupuncture point TENS"],
  simple:"TENS electrodes are placed where the stimulation can reach the nerves carrying the pain: around the painful area, along the nerve, over the matching spinal segment or over acupuncture or trigger points. TENS helps many acute and chronic pains, but must not be used near pacemakers, the front of the neck or over a pregnant uterus.",
  flow:["Assess pain area, nerve and spinal segment","Choose placement: local, nerve, dermatome, segment or points","Place electrodes at least 2-3 cm apart","Set mode and increase to strong comfortable level","Check contraindications and skin before and after","Teach home use and review response"],
  exam:[
    {h:"Principles of placement", p:["Aim: stimulate A-beta fibres that enter the same spinal segments as the pain (segmental effect).","Electrodes on intact, sensate skin; at least about 2-3 cm apart to avoid current concentration; larger electrodes for comfort.","If response is poor, change placement before increasing intensity; patient feels tingling in or around the painful area."]},
    {h:"Methods of electrode placement", p:["Local (bracketing): electrodes on either side of or around the painful area (e.g. either side of the knee joint line).","Along the peripheral nerve supplying the area (e.g. ulnar nerve at the elbow for ulnar-side hand pain).","Dermatomal: within the dermatome of the painful area.","Paravertebral (segmental): over the spinal nerve roots at the matching segment, e.g. lumbar paraspinals for sciatica.","Acupuncture, trigger or motor points (mainly with acupuncture-like TENS).","Contralateral placement (when the painful side cannot be used, e.g. allodynia, burns, amputation stump) and crossed (criss-cross) placements with dual channels."]},
    {h:"Common clinical placements", p:["Labour: two channels paravertebrally at T10-L1 (early labour) and S2-S4 (later), patient-controlled boost during contractions.","Low back pain and sciatica: paraspinal at the painful level, second channel along the dermatome or posterior thigh.","Knee OA: medial and lateral joint line or bracketing the painful area.","Post-operative pain: sterile electrodes parallel to the incision.","Phantom limb pain: on the stump away from the wound, the contralateral limb, or the nerve proximally."]},
    {h:"Uses (indications)", p:["Acute pain: post-operative pain, fractures (with care), sprains, dysmenorrhoea, labour pain.","Chronic pain: osteoarthritis, chronic low back and neck pain, neuropathic pain (post-herpetic neuralgia, diabetic neuropathy, phantom pain), fibromyalgia (as an adjunct), cancer pain (palliative care, avoiding direct placement over a tumour unless agreed by the team).","Dosage reminder: conventional 80-150 Hz, 50-100 microseconds, 30-60 minutes or longer as needed; acupuncture-like 2-4 Hz, 100-300 microseconds, 20-30 minutes."]},
    {h:"Contraindications and precautions", p:["Contraindications: demand pacemaker or implanted defibrillator (unless cleared by cardiology), over the anterior neck or carotid sinus (hypotension, laryngeal spasm), over the eyes, over the pregnant uterus or abdomen (except labour TENS), transcranial placement without specialist protocol, broken skin or open wounds (except sterile post-operative use), undiagnosed pain.","Precautions: epilepsy (avoid head and neck), impaired sensation or cognition, malignancy in the area, active bleeding, DVT, skin allergy to electrodes or gel, heart disease, driving or operating machinery while using TENS.","Dangers: skin irritation or burns from poor contact, electric shock with faulty units, interference with monitoring equipment."]},
    {h:"Conclusion", p:["Good TENS results depend on placement over the correct segment and adequate intensity; it is safe, cheap and suited to home use when screened properly and combined with active rehabilitation."]}
  ],
  tip:"Draw a back with two channels: one pair paraspinal at L4-L5 and one pair along the posterior thigh dermatome. Beside it sketch a pregnant woman's back with electrodes at T10-L1 and S2-S4 and label 'labour TENS'.",
  evidence:[["TENS for acute and chronic pain (meta-TENS)","Lower pain during or immediately after treatment vs placebo","Low certainty, moderate effect"],["TENS for labour pain","Some women report less severe pain; little effect on outcomes of birth","Low"],["TENS for knee OA","Possible short-term pain relief; trials inconsistent","Low"]],
  evidenceSource:"Johnson et al., BMJ Open 2022 (meta-TENS); Cochrane review of TENS for labour pain (Dowswell et al. 2009)",
  outcomes:[["NPRS or VAS","Pain intensity during and after TENS"],["Patient-specific functional scale","Function with pain relief"],["Analgesic use","Medication reduction"]],
  recent:["The meta-TENS study (Johnson et al., BMJ Open 2022) found TENS reduced pain intensity during or immediately after treatment across many conditions, with low-certainty evidence and few serious adverse events."],
  mnemonic:{word:"LANDS", items:[["L","Local bracketing"],["A","Acupuncture or trigger points"],["N","Nerve trunk"],["D","Dermatome"],["S","Spinal segment (paraspinal)"]], extra:"Never: pacemaker, anterior neck, pregnant uterus (except labour), eyes."},
  example:"A 28-year-old in Coimbatore in early labour uses a two-channel TENS unit at T10-L1 and S2-S4, pressing the boost button during contractions, after the midwife checks there is no water birth planned.",
  flags:["Demand pacemaker or ICD","Anterior neck or carotid sinus","Over the pregnant uterus (except labour TENS)","Using TENS in water or while driving"],
  viva:[["Where are electrodes placed for labour TENS?","Paravertebrally at T10-L1 and S2-S4."],["What is contralateral placement?","Electrodes on the opposite limb or side when the painful side cannot be stimulated."],["Why avoid the anterior neck?","Stimulation of the carotid sinus can cause hypotension and bradycardia, and laryngeal spasm is possible."]],
  refs:[{c:"Johnson MI, Paley CA, Jones G, Mulvey MR, Wittkopf PG. Efficacy and safety of TENS for acute and chronic pain in adults: a systematic review and meta-analysis of 381 studies (the meta-TENS study). BMJ Open. 2022.", q:"meta-TENS study Johnson BMJ Open 2022"},{b:"cameron", ch:"Electrical currents for pain control"},{c:"Dowswell T, Bedwell C, Lavender T, Neilson JP. Transcutaneous electrical nerve stimulation (TENS) for pain relief in labour. Cochrane Database Syst Rev. 2009.", q:"Dowswell TENS pain relief labour Cochrane"}],
  keywords:"TENS electrode placement dermatome segmental paravertebral acupuncture point labour TENS uses indications contraindications pacemaker carotid sinus",
  mcq:[["In labour TENS, the upper pair of electrodes is placed at:",["C5-C6","L4-L5","S2-S4","T10-L1"],3,"T10-L1 covers the uterine pain of early labour; S2-S4 is for later labour."],["TENS is contraindicated over:",["The lumbar spine in back pain","The anterior neck","The knee joint line","The forearm"],1,"Carotid sinus stimulation may cause hypotension and bradycardia."]]
},
{
  id:"el-iontophoresis-ions", title:"Iontophoresis: ions used and clinical indications", subject:"Electrotherapy", region:"Skin and superficial tissues", stages:"steps",
  aliases:["ions used in iontophoresis","iontophoresis drugs","polarity of ions","dexamethasone iontophoresis","tap water iontophoresis","acetic acid iontophoresis"],
  simple:"In iontophoresis, a drug ion is pushed into the skin from the electrode with the same charge. So each drug must be placed under the correct pole: negative ions under the cathode and positive ions under the anode. Different ions treat different problems, such as inflammation, calcium deposits, scars, sweating or local pain.",
  flow:["Identify condition and goal","Select ion and its charge","Place drug under the electrode of same polarity","Like charges repel the ion into skin","Ion enters through sweat ducts and hair follicles","Local action, then spread by circulation"],
  exam:[
    {h:"Principle of ion selection", p:["Like charges repel: negative ions are delivered from the cathode (negative electrode), positive ions from the anode (positive electrode).","The drug must be ionisable in solution and of small molecular size; use an aqueous solution of known strength.","Penetration is shallow (a few millimetres); best for superficial targets: tendons, bursae, fascia, skin."]},
    {h:"Negative ions (from cathode)", p:["Dexamethasone sodium phosphate (0.4 percent or 4 mg/ml): anti-inflammatory for tendinopathy, lateral epicondylalgia, plantar fasciitis, bursitis, de Quervain's.","Acetate (acetic acid 2-5 percent): sclerolytic, claimed to dissolve calcific deposits (calcific tendinitis, myositis ossificans); weak evidence.","Salicylate (sodium salicylate 2 percent): analgesic and anti-inflammatory; avoid in aspirin allergy.","Iodine (iodide 5-10 percent ointment or solution): sclerolytic and antiseptic for scars and adhesions (adhesive capsulitis claims); avoid in iodine or seafood allergy.","Chloride (sodium chloride 2 percent): sclerolytic for scar tissue and keloids."]},
    {h:"Positive ions (from anode)", p:["Lidocaine (lignocaine) 2-4 percent, often with adrenaline: local anaesthesia before minor procedures, trigger point pain, neuromas.","Hyaluronidase: breaks down hyaluronic acid to disperse local oedema and haematoma.","Magnesium (magnesium sulphate 2 percent): muscle relaxant and vasodilator for spasm.","Calcium (calcium chloride 2 percent): stabilising effect on excitable membranes, historically for spasm.","Zinc (zinc oxide ointment): antiseptic, promotes healing of ulcers and wounds; copper sulphate 2 percent: antifungal (dermatophytosis); hydrocortisone in some protocols."]},
    {h:"Tap water iontophoresis", p:["Plain tap water in trays with both hands or feet immersed; polarity reversed half-way through.","Treatment of choice for palmar and plantar hyperhidrosis: about 15-20 mA (as tolerated) for 15-20 minutes, several times a week until controlled, then maintenance.","Mechanism thought to be temporary blockage of sweat duct function."]},
    {h:"Clinical indications summary", p:["Inflammation: tendinopathy, bursitis, plantar fasciitis (dexamethasone).","Calcific deposits (acetic acid), scars and adhesions (iodine, chloride).","Local anaesthesia (lidocaine), oedema (hyaluronidase), hyperhidrosis (tap water), fungal infection (copper), wounds and ulcers (zinc)."]},
    {h:"Conclusion", p:["Correct choice of ion, polarity and concentration is the core of iontophoresis; evidence is strongest for tap water in hyperhidrosis and modest for dexamethasone in superficial musculoskeletal inflammation."]}
  ],
  tip:"Make a two-column table headed 'Cathode (-)' and 'Anode (+)'. List dexamethasone, acetate, salicylate, iodine, chloride under cathode; lidocaine, hyaluronidase, magnesium, calcium, zinc, copper under anode, each with one indication.",
  evidence:[["Tap water iontophoresis for hyperhidrosis","Reduces sweating in most patients","Moderate"],["Dexamethasone iontophoresis for plantar fasciitis","Short-term pain relief","Low-moderate"],["Acetic acid iontophoresis for calcific tendinitis","No clear benefit over exercise or placebo","Low"]],
  evidenceSource:"Cameron, Physical Agents in Rehabilitation; Robertson et al., Electrotherapy Explained",
  outcomes:[["NPRS and first-step pain","Pain in plantar fasciitis"],["Hyperhidrosis Disease Severity Scale","Sweating severity"],["X-ray deposit size","Calcific deposit change"]],
  recent:["Pre-filled, battery-powered patch iontophoresis systems now allow controlled drug delivery with lower current over longer times."],
  mnemonic:{word:"Like repels like", items:[["-","Dexa, Acetate, Salicylate, Iodine, Chloride (DASIC)"],["+","Lidocaine, Hyaluronidase, Magnesium, Calcium, Zinc, Copper"],["Water","Tap water, polarity reversed, for sweating"]], extra:"Drug under the electrode with the same charge."},
  example:"A 40-year-old traffic policeman in Chennai with plantar fasciitis receives dexamethasone iontophoresis from the cathode over the medial heel, alongside calf stretching and footwear advice.",
  flags:["Drug allergy (aspirin for salicylate, iodine or seafood allergy for iodine)","Wrong polarity: drug not delivered and burn risk","Broken skin or impaired sensation under the electrode"],
  viva:[["Under which electrode is dexamethasone placed?","The cathode (negative), as it is a negative ion."],["Which ion is used for calcific deposits?","Acetate from acetic acid, from the cathode."],["What is used for hyperhidrosis?","Tap water iontophoresis with polarity reversal."]],
  refs:[{b:"cameron", ch:"Electrical currents for iontophoresis"},{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Iontophoresis (medical ionisation)."},{b:"prentice", ch:"Iontophoresis"}],
  keywords:"iontophoresis ions polarity dexamethasone acetic acid salicylate iodine chloride lidocaine hyaluronidase magnesium zinc copper tap water hyperhidrosis",
  mcq:[["Lidocaine iontophoresis uses which electrode as the active pad?",["Anode","Cathode","Either, no difference","Dispersive only"],0,"Lidocaine is a positive ion, repelled from the anode."],["Tap water iontophoresis is indicated for:",["Calcific tendinitis","Keloid","Palmar hyperhidrosis","Fungal nail infection"],2,"It is a well-supported treatment for hyperhidrosis of hands and feet."]]
},
{
  id:"el-iontophoresis-dosage", title:"Iontophoresis: dosage, dangers and contraindications", subject:"Electrotherapy", region:"Skin and superficial tissues", stages:"steps",
  aliases:["iontophoresis dose","mA-min","current density iontophoresis","iontophoresis burns","dangers of iontophoresis","contraindications of iontophoresis"],
  simple:"Iontophoresis dose is counted as current multiplied by time (mA-min), usually 40-80 mA-min. The current must be kept low per square centimetre of electrode, because direct current makes acid and alkali under the pads that can burn the skin. Allergy to the drug and poor skin sensation are the main reasons not to use it.",
  flow:["Choose drug, polarity and electrode sizes","Calculate dose: mA x minutes","Keep current density below safe limits","Increase current slowly, check skin often","Reduce to zero, remove and inspect skin","Record dose; space sessions to protect skin"],
  exam:[
    {h:"Dosage", p:["Dose = current (mA) x time (minutes); typical 40-80 mA-min per session (e.g. 4 mA for 10 minutes = 40 mA-min, or 2 mA for 20 minutes).","Current usually 1-4 mA (up to about 5 mA on larger electrodes); buffered patch systems use lower current over longer time (e.g. low mA for hours).","Number of sessions: often 3-6 sessions on alternate days for dexamethasone; tap water for hyperhidrosis several sessions a week then maintenance."]},
    {h:"Current density and electrodes", p:["Current density = current / electrode area; keep at or below about 0.5 mA/cm2 for the cathode and about 1.0 mA/cm2 for the anode (many clinicians stay lower, about 0.1-0.5 mA/cm2).","Dispersive electrode should be larger (often about twice the active) to lower density; the cathode is often made larger because alkaline burns are more serious.","Electrodes placed a few centimetres apart (at least the diameter of the active electrode); further apart spreads current more deeply but less locally."]},
    {h:"Technique points for safety", p:["Check skin sensation and integrity; clean with water or alcohol, no shaving immediately before.","Correct polarity and drug concentration; buffered electrodes reduce pH change.","Increase current slowly; check skin at intervals; reduce current if burning or stinging.","After treatment, slight erythema and tingling are normal; advise no heat or friction to the area for some hours."]},
    {h:"Dangers", p:["Chemical burns: alkaline (sodium hydroxide) under the cathode and acid (hydrochloric acid) under the anode; alkaline burns are deeper and slower to heal and may be painless at first.","Thermal or electrical burns from high current density, dry or uneven pads, or metal touching skin.","Allergic or systemic drug reactions (e.g. to salicylates, iodine, lidocaine, steroids).","Electric shock from faulty equipment; overdose with too many sessions (e.g. steroid side effects)."]},
    {h:"Contraindications", p:["Known sensitivity or allergy to the drug or ion.","Broken skin, recent scar, rash or dermatitis at the site (except where intended), impaired sensation, unreliable or confused patient.","Cardiac pacemaker or implanted electrical device; electrodes across the chest or anterior neck.","Metal implants close to the surface under the electrode, pregnancy (systemic drugs, abdomen and low back), malignancy in the area, recent haemorrhage.","Drug-specific: steroids in active infection or diabetes (caution), aspirin-sensitive asthma for salicylates."]},
    {h:"Conclusion", p:["Iontophoresis is safe when the dose is calculated in mA-min, current density is kept low with correctly sized electrodes, polarity is right and patients are screened for allergy and sensation."]}
  ],
  tip:"Write the formula boxes: Dose (mA-min) = mA x min, and Current density = mA / cm2. Draw two electrodes, a small active pad labelled with the drug and a larger dispersive pad, with 'NaOH under cathode' and 'HCl under anode'.",
  evidence:[["Limiting current density","Reduces risk of chemical burns","Expert consensus and case reports"],["Dexamethasone iontophoresis (40-80 mA-min) for tendinopathy","Short-term relief; long-term benefit unclear","Low"]],
  evidenceSource:"Cameron, Physical Agents in Rehabilitation; Prentice, Therapeutic Modalities in Rehabilitation",
  outcomes:[["Skin inspection record","Safety, burns or irritation"],["NPRS","Pain relief"]],
  recent:["Buffered and pre-filled electrode systems that control pH under the electrode have reduced burn rates and allow lower-current, longer-duration delivery."],
  mnemonic:{word:"DOSE", items:[["D","Density: under 0.5 mA/cm2 at cathode"],["O","Obtain allergy history"],["S","Size: dispersive bigger"],["E","Equation: mA x min = 40-80"]], extra:"Cathode burns are alkaline, deeper and more dangerous."},
  example:"A student in Puducherry calculates 3 mA for 13-14 minutes to deliver 40 mA-min of dexamethasone over a 10 cm2 cathode (0.3 mA/cm2) for lateral elbow pain, and checks the skin every few minutes.",
  flags:["Chemical burn, especially alkaline under cathode","Allergy to the drug or ion","Impaired sensation or broken skin","Pacemaker or current path across the chest"],
  viva:[["How is iontophoresis dose expressed?","In mA-min: current in mA multiplied by time in minutes, usually 40-80 mA-min."],["Why is the cathode electrode often made larger?","To lower current density there, because alkaline burns are more serious."],["Name a contraindication specific to salicylate iontophoresis.","Aspirin allergy or aspirin-sensitive asthma."]],
  refs:[{b:"cameron", ch:"Electrical currents for iontophoresis"},{b:"prentice", ch:"Iontophoresis"},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Iontophoresis."}],
  keywords:"iontophoresis dosage mA-min current density electrode size chemical burn alkaline cathode acid anode contraindications allergy",
  mcq:[["A dose of 40 mA-min is delivered by:",["40 mA for 10 minutes","4 mA for 10 minutes","1 mA for 4 minutes","10 mA for 40 minutes"],1,"4 mA x 10 min = 40 mA-min."],["The more dangerous chemical burn in iontophoresis occurs under the:",["Anode, due to acid","Neither, iontophoresis cannot burn","Both equally","Cathode, due to alkali"],3,"Sodium hydroxide forms under the cathode, causing deeper alkaline burns."]]
},
{
  id:"el-ifc-production", title:"Interferential current: production, static (classical) and dynamic (vector) fields", subject:"Electrotherapy", region:"Deep tissues", stages:"steps",
  aliases:["production of IFC","interference of currents","beat frequency","static interferential field","dynamic interferential","rotating vector","clover-leaf pattern"],
  simple:"Interferential current is made by crossing two medium frequency currents of slightly different frequencies inside the body. Where they meet, they add and cancel in turn, creating a slow 'beat' that nerves respond to. In the static field the strongest effect is in fixed clover-leaf zones; in the dynamic (vector) field the zone is moved around to cover more tissue.",
  flow:["Two circuits: e.g. 4000 Hz and 4100 Hz","Currents cross in the target tissue","Constructive and destructive interference occurs","Beat (AMF) equals the difference: 100 Hz","Static field: clover-leaf zones at 45 degrees","Dynamic field: zone rotates to cover more area"],
  exam:[
    {h:"Definition", p:["Interferential current (IFC) is the transcutaneous application of two medium frequency alternating currents, slightly out of phase in frequency, which interfere in the tissues to produce a low frequency amplitude-modulated current (AMF or beat frequency).","Developed by Nemec in the 1950s to obtain low frequency effects in deep tissues without the discomfort of low frequency currents at the skin."]},
    {h:"Production and interference", p:["Circuit A carries a fixed frequency (e.g. 4000 Hz); circuit B a variable frequency (e.g. 4000-4250 Hz).","Where the two currents meet, they sum algebraically: when in phase, amplitudes add (constructive interference); when out of phase, they cancel (destructive interference).","The resulting current has a medium frequency carrier (about the mean, 4050 Hz) whose amplitude rises and falls at the difference frequency: AMF = fB - fA (e.g. 4100 - 4000 = 100 Hz).","Carrier frequencies: commonly 4000 Hz (deeper, comfortable) or 2000 Hz (better for muscle stimulation)."]},
    {h:"Static (classical) interference field", p:["Four electrodes, two crossing circuits (quadripolar), equal current in each circuit.","Modulation depth varies through the field: 100 percent along the diagonals at 45 degrees to the two current paths, producing a clover-leaf (four-leaf) pattern; little or no modulation along the lines of the circuits.","Target tissue must lie within the clover-leaf; precise electrode placement is needed so the lesion sits at the crossing point."]},
    {h:"Dynamic (vector, rotating vector) field", p:["The machine rhythmically varies the amplitude of one or both circuits, so the zone of full modulation swings or rotates (e.g. through 45-90 degrees or a full 360 degree scan).","Advantages: covers a larger area, useful when the lesion is poorly localised or diffuse (e.g. back pain), and reduces accommodation.","Variants: scanning (isoplanar swing) and rotating vector with automatic rotation; some units allow manual vector placement to target a specific zone."]},
    {h:"Premodulated (bipolar) IFC", p:["Two electrodes; interference is produced inside the machine, so the current is already modulated when it leaves.","Modulation depth is 100 percent all along the current path; simple to apply in small areas, but no deep interference advantage."]},
    {h:"Advantages over low frequency currents", p:["Lower skin impedance at medium frequency: less sensory discomfort and less current needed at the skin.","Low frequency effects (pain gate, endorphin release, muscle contraction) generated deeper in tissue.","No net direct current, so no chemical burns."]},
    {h:"Conclusion", p:["IFC is produced by interference of two medium frequency currents; static fields give fixed clover-leaf effects, while vector (dynamic) fields move the zone to cover larger, diffuse lesions."]}
  ],
  tip:"Draw two sine waves of slightly different frequency and below them the resultant wave with an envelope rising and falling (beat). Next draw a square of four electrodes with two crossing circuits and shade the clover-leaf at 45 degrees; add a curved arrow for the rotating vector.",
  evidence:[["IFC added to other treatment for musculoskeletal pain","Short-term pain reduction vs control","Low-moderate"],["Deep interference advantage of quadripolar over premodulated IFC","Laboratory studies question larger depth effect","Low"]],
  evidenceSource:"Fuentes et al., Phys Ther 2010; Robertson et al., Electrotherapy Explained; Watson, Electrotherapy: Evidence-Based Practice",
  outcomes:[["NPRS","Pain relief"],["Pressure pain threshold","Local hypoalgesia"]],
  recent:["Laboratory work by Ward and colleagues suggested that, despite theory, quadripolar IFC does not clearly deliver more current to deep tissue than premodulated IFC, and comfort differences may be small."],
  mnemonic:{word:"AMF = B minus A", items:[["A","Fixed 4000 Hz"],["B","Variable 4000-4250 Hz"],["AMF","Difference 0-250 Hz"],["Clover","Full modulation at 45 degrees"]], extra:"Static = fixed clover; vector = rotating clover."},
  example:"For diffuse chronic low back pain in a software engineer in Bengaluru, the therapist chooses quadripolar IFC with rotating vector so the full-modulation zone sweeps across both paraspinal areas.",
  flags:["Pacemaker or implanted stimulator","Over the pregnant uterus, abdomen or low back in pregnancy","Malignancy, DVT or infection in the field","Electrodes crossing the chest in cardiac disease"],
  viva:[["How is AMF produced in quadripolar IFC?","By interference of two medium frequency currents; AMF equals their frequency difference."],["Where is modulation depth maximum in a static field?","Along the diagonals at 45 degrees to the circuits."],["Why use a rotating vector?","To move the zone of maximal modulation and cover a larger or poorly localised area."]],
  refs:[{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Interferential therapy."},{c:"Watson T (ed). Electrotherapy: Evidence-Based Practice. 12th ed. Chapter: Interferential therapy."},{b:"cameron", ch:"Electrical currents for pain control"}],
  keywords:"interferential current production interference beat frequency AMF static classical field clover leaf dynamic vector rotating premodulated quadripolar Nemec",
  mcq:[["If circuit A is 4000 Hz and circuit B is 4080 Hz, the AMF is:",["4040 Hz","8080 Hz","80 Hz","40 Hz"],2,"AMF is the difference between the two frequencies."],["In a static quadripolar field, 100 percent modulation lies:",["On the diagonals at 45 degrees","Under each electrode","Along each circuit","Only on the skin surface"],0,"The clover-leaf zones lie at 45 degrees to the circuits."]]
},
{
  id:"el-ifc-parameters", title:"IFC parameters: bipolar and quadripolar, sweep, AMF and suction electrodes", subject:"Electrotherapy", region:"Deep tissues", stages:"steps",
  aliases:["IFT parameters","AMF selection","sweep frequency","sweep pattern","suction electrodes","vacuum electrodes","bipolar vs quadripolar"],
  simple:"With IFC the therapist chooses the carrier frequency, the beat frequency (AMF), a sweep that changes the AMF to stop the nerves getting used to it, and the electrode method: two electrodes (bipolar) or four (quadripolar). Suction electrodes hold on with a vacuum and add a gentle massage effect.",
  flow:["Choose carrier: 4000 Hz deep, 2000 Hz for muscle","Choose base AMF for the goal","Add sweep to reduce accommodation","Choose bipolar or quadripolar placement","Choose plate or suction electrodes","Intensity strong but comfortable, 10-20 minutes"],
  exam:[
    {h:"Carrier frequency", p:["4000 Hz: lower skin impedance, more comfortable, deeper sensation; most common.","2000 Hz: often used for muscle stimulation, as it can produce stronger contractions at tolerable intensity."]},
    {h:"AMF (beat frequency) selection", p:["80-150 Hz (e.g. 100 Hz): pain relief by gate control, acute pain.","1-10 Hz (e.g. 2-5 Hz): opioid-mediated relief, chronic pain; twitches can pump fluid.","10-25 Hz: muscle twitch and vascular effects; 25-50 Hz: tetanic muscle contraction (e.g. pelvic floor, quadriceps).","0-10 Hz sweeps: claimed to help oedema and circulation (weak evidence)."]},
    {h:"Sweep (frequency modulation)", p:["The AMF varies automatically between a base and a top frequency (e.g. 80-120 Hz, 1-100 Hz) to reduce accommodation and stimulate a wider range of fibres.","Sweep patterns: 1:1 (1 s up, 1 s down), 6:6, triangular (gradual up and down), rectangular (abrupt switch between two frequencies) and 6:1:6 (hold and change).","Narrow sweep for a specific effect; wide sweep for a broader effect when the target is unclear; no strong evidence that one pattern is superior."]},
    {h:"Bipolar versus quadripolar", p:["Bipolar (premodulated): 2 electrodes, modulation made in the machine, 100 percent depth throughout; for small areas (wrist, ankle, hand), muscle stimulation and pelvic floor.","Quadripolar: 4 electrodes, 2 crossing circuits; interference in the tissue; for larger and deeper areas (knee, shoulder, low back); electrodes placed so the target lies at the crossing point.","Quadripolar with vector scan or rotation for diffuse lesions."]},
    {h:"Electrodes", p:["Carbon rubber plates with wet sponges or gel: secured with straps; even contact essential.","Suction (vacuum) electrodes: cups with an internal sponge, held by negative pressure from a pump; quick to apply on curved or large areas (back, shoulder); pulsed suction gives a massage-like effect said to improve circulation.","Suction pressure kept low to moderate (just enough to hold); avoid on fragile skin, bruising tendency, anticoagulation, varicose veins and acute injury; check skin for petechiae or bruising."]},
    {h:"Intensity, time and frequency of treatment", p:["Intensity: strong but comfortable tingling (sensory) or visible contraction (motor); readjust as accommodation occurs.","Time: about 10-20 minutes (up to 30); daily or alternate days; review after about 6 sessions."]},
    {h:"Conclusion", p:["IFC dosage combines carrier, AMF, sweep, electrode method and intensity; choices should match the goal, with the understanding that evidence for specific settings is limited."]}
  ],
  tip:"Draw a table with columns Goal, AMF, Sweep, Method: pain acute (100 Hz, 80-120), chronic pain (2-5 Hz, 1-10), muscle (25-50 Hz, none, bipolar). Add a sketch of a suction cup with sponge, vacuum line and arrows showing pulsed suction.",
  evidence:[["Effect of different sweep settings on pain","No clear difference between sweep patterns in laboratory studies","Low"],["IFC for knee OA pain","Possible short-term pain relief","Low"]],
  evidenceSource:"Robertson et al., Electrotherapy Explained; Watson, Electrotherapy: Evidence-Based Practice",
  outcomes:[["NPRS","Pain relief"],["Skin inspection","Suction-related bruising"],["Girth","Oedema response"]],
  recent:["Experimental studies comparing AMF values and sweep settings have mostly found similar pain threshold changes, so clinicians are encouraged to choose comfortable settings and adequate intensity."],
  mnemonic:{word:"CASE", items:[["C","Carrier 4000 or 2000 Hz"],["A","AMF for the goal"],["S","Sweep to stop accommodation"],["E","Electrodes: 2 or 4, plate or suction"]], extra:"100 Hz for acute pain, 2-5 Hz for chronic pain, 25-50 Hz for contraction."},
  example:"A 58-year-old woman in Madurai with knee OA receives quadripolar IFC, 4000 Hz carrier, AMF 90-130 Hz with triangular sweep, 15 minutes, followed by quadriceps exercises.",
  flags:["Suction cups on fragile skin, varicose veins or anticoagulated patients","Pacemaker or pregnancy (abdomen and pelvis)","Unequal electrode contact causing burns"],
  viva:[["What is sweep in IFC?","Automatic variation of the AMF between two values to reduce accommodation."],["When is bipolar IFC preferred?","For small areas and muscle stimulation, where premodulated current gives 100 percent modulation along its path."],["What are suction electrodes?","Cup electrodes held by a vacuum pump, quick to apply and giving a massage-like effect."]],
  refs:[{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Interferential therapy."},{c:"Watson T (ed). Electrotherapy: Evidence-Based Practice. 12th ed. Chapter: Interferential therapy."},{b:"prentice", ch:"Interferential current"}],
  keywords:"IFC parameters carrier frequency AMF sweep 1:1 6:6 triangular bipolar quadripolar premodulated suction vacuum electrodes",
  mcq:[["An AMF commonly chosen for acute pain relief is:",["2 Hz","0.5 Hz","4000 Hz","100 Hz"],3,"High AMF (80-150 Hz) targets gate control."],["Suction electrodes should be avoided in:",["Chronic low back pain","Patients on anticoagulants with easy bruising","Knee OA","Shoulder stiffness"],1,"Negative pressure can cause bruising in fragile or anticoagulated patients."]]
},
{
  id:"el-ifc-effects-dangers", title:"IFC: physiological effects, indications, contraindications and dangers", subject:"Electrotherapy", region:"Deep tissues", stages:"steps",
  aliases:["effects of IFT","IFT indications","IFT contraindications","dangers of IFC","interferential uses","IFT for pain"],
  simple:"IFC can reduce pain, make muscles contract and may help circulation and swelling. It is used for many joint and soft tissue problems such as knee OA, back pain and stress incontinence. It must not be used near pacemakers, over the pregnant abdomen or over tumours, and burns or shocks can happen if electrodes are faulty.",
  flow:["AMF stimulates sensory, motor and autonomic fibres","Pain relief by gate control and endorphins","Muscle contraction and muscle pump","Possible circulation and oedema effects","Screen contraindications before applying","Monitor for burns, shock and discomfort"],
  exam:[
    {h:"Physiological effects", p:["Sensory nerve stimulation: tingling, pain gating at high AMF; endogenous opioid release at low AMF.","Motor nerve stimulation: twitch (1-10 Hz) or tetanic contraction (25-50 Hz); muscle pumping aids venous and lymphatic flow.","Circulatory effects: increased local blood flow from muscle contraction and possibly autonomic effects (claimed for low AMF); evidence limited.","Possible acceleration of healing and reduction of oedema (claims mainly from older work)."]},
    {h:"Indications", p:["Pain: knee OA, chronic low back pain, neck pain, shoulder pain, post-traumatic pain, myofascial pain.","Musculoskeletal injuries: sprains, contusions, haematoma (subacute), joint effusion.","Muscle stimulation and re-education: quadriceps inhibition, pelvic floor (stress incontinence), weak abdominal muscles.","Oedema reduction, delayed fracture healing (claimed), circulatory disorders (claimed)."]},
    {h:"Contraindications", p:["Cardiac pacemaker or implanted defibrillator; electrodes across the chest in serious cardiac disease.","Pregnancy: over the abdomen, pelvis or low back.","Malignancy in the area, active TB, acute infection or fever.","Recent haemorrhage or risk of bleeding, haemophilia; DVT or thrombophlebitis (risk of embolus).","Broken skin, dermatitis, impaired sensation, unreliable or confused patient, very young children.","Over the anterior neck or carotid sinus, eyes, head (in epilepsy).","Metal implants (relative): many authorities allow IFC near metal since currents are alternating, but caution and close monitoring."]},
    {h:"Dangers", p:["Electric shock from faulty apparatus or damaged leads.","Burns from uneven electrode contact, dry sponges or high current density.","Muscle soreness or fatigue from vigorous motor stimulation; autonomic reactions such as faintness or nausea.","Bruising from suction electrodes; aggravation of symptoms in acute inflammation if too intense."]},
    {h:"Precautions and safety", p:["Test sensation; check equipment and leads; intensity at zero before switching on.","Equal-sized, well-wetted electrodes; even pressure; turn current down before removing electrodes.","Keep away from shortwave diathermy units operating nearby (interference)."]},
    {h:"Conclusion", p:["IFC is widely used for pain and muscle stimulation; it is safe when screened and monitored, but it works best as an adjunct to active rehabilitation, as stand-alone evidence is limited."]}
  ],
  tip:"Draw a quadripolar knee placement and around it four boxes: effects (pain, muscle, circulation), indications, contraindications and dangers. Use red ink for pacemaker, pregnancy and malignancy.",
  evidence:[["IFC with other treatments for musculoskeletal pain","Short-term pain reduction","Low-moderate"],["IFC alone vs placebo","No clear difference in several trials","Low"],["IFC for stress urinary incontinence","Some trials show benefit; quality low","Low"]],
  evidenceSource:"Fuentes et al., Phys Ther 2010; Watson, Electrotherapy: Evidence-Based Practice",
  outcomes:[["NPRS","Pain relief"],["WOMAC or ODI","Function in knee OA or back pain"],["Pad test","Continence change"]],
  recent:["Fuentes et al. (Phys Ther 2010) concluded IFC is more effective as an adjunct to other interventions than on its own for musculoskeletal pain."],
  mnemonic:{word:"No PPM", items:[["P","Pacemaker"],["P","Pregnancy over abdomen, pelvis, back"],["M","Malignancy"]], extra:"Also: DVT, bleeding, infection, broken skin, poor sensation, anterior neck."},
  example:"A 50-year-old shopkeeper in Erode with chronic low back pain has IFC as part of a programme of education and graded exercise; the therapist first confirms he has no pacemaker and no history of cancer.",
  flags:["Pacemaker or ICD","Pregnancy (abdomen, pelvis, low back)","Malignancy, DVT or active infection in the area","Burns from poor electrode contact"],
  viva:[["Name three contraindications to IFC.","Pacemaker, pregnancy over the abdomen or pelvis, and malignancy in the area."],["Why can IFC cause muscle soreness?","Vigorous motor stimulation at 25-50 Hz produces strong repeated contractions."],["Is metal a contraindication to IFC?","A relative precaution; IFC has no net DC, so many allow it with caution."]],
  refs:[{c:"Fuentes JP, Armijo Olivo S, Magee DJ, Gross DP. Effectiveness of interferential current therapy in the management of musculoskeletal pain: a systematic review and meta-analysis. Phys Ther. 2010;90:1219-1238.", q:"Fuentes interferential current musculoskeletal pain meta-analysis"},{c:"Watson T (ed). Electrotherapy: Evidence-Based Practice. 12th ed. Chapter: Interferential therapy."},{b:"cameron", ch:"Electrical currents for pain control"}],
  keywords:"IFC IFT physiological effects indications contraindications dangers pacemaker pregnancy malignancy DVT burns suction bruising",
  mcq:[["Which is an absolute contraindication to IFC?",["Cardiac pacemaker","Chronic knee OA","Mild muscle spasm","Old healed fracture"],0,"Electrical fields can interfere with pacemaker function."],["Low AMF (2-5 Hz) is mainly used to:",["Produce heat","Deliver ions","Stimulate endorphin release for chronic pain","Measure chronaxie"],2,"Low frequency stimulation is linked to opioid-mediated descending inhibition."]]
},
{
  id:"el-matter-atoms", title:"Properties of matter; atoms and molecules (biophysics for physical modalities)", subject:"Electrotherapy", region:"Biophysics", stages:"steps",
  aliases:["properties of matter","structure of atom","atoms and molecules","electron theory","ions","conductors and insulators","states of matter"],
  simple:"Everything is made of atoms joined into molecules. An atom has a nucleus of protons and neutrons with electrons around it; when atoms gain or lose electrons they become ions. These ideas explain why metals and body fluids conduct electricity, why some materials insulate, and how heat, water and wax behave in therapy.",
  flow:["Matter: solid, liquid, gas (and plasma)","Atoms: protons, neutrons in nucleus; electrons in shells","Molecules: atoms bonded together","Ions form by losing or gaining electrons","Free electrons or ions make conductors","Physical properties guide choice of modality"],
  exam:[
    {h:"Matter and its states", p:["Matter is anything that has mass and occupies space; it exists as solid (fixed shape and volume), liquid (fixed volume, takes shape of container) and gas (neither fixed); plasma is ionised gas.","Change of state needs latent heat (e.g. melting of paraffin wax releases latent heat as it solidifies on the skin, giving prolonged heating)."]},
    {h:"Properties of matter relevant to physiotherapy", p:["Density and specific gravity: buoyancy in hydrotherapy (body specific gravity about 0.97 versus water 1.0, so the body floats).","Specific heat: heat needed to raise 1 g by 1 degree C; water has high specific heat, so water-based packs store heat well; wax has low specific heat and low conductivity, so it can be tolerated at higher temperature.","Thermal conductivity: metals conduct heat fast (risk of burns from metal in heat fields); fat and air insulate.","Elasticity (Hooke's law), viscosity (resistance of water to movement in hydrotherapy) and surface tension; pressure (Pascal's law) and hydrostatic pressure."]},
    {h:"Structure of the atom", p:["Nucleus: protons (positive) and neutrons (neutral); atomic number = number of protons; mass number = protons + neutrons.","Electrons (negative, very light) occupy shells (K, L, M...) around the nucleus; a neutral atom has equal protons and electrons.","Outermost (valence) electrons decide chemical bonding and electrical conductivity; isotopes have the same atomic number but different mass numbers."]},
    {h:"Molecules, bonds and ions", p:["Molecule: smallest particle of a substance that can exist independently, formed by atoms joined by bonds.","Ionic bond: transfer of electrons (e.g. sodium chloride, Na+ and Cl-); covalent bond: sharing of electrons (e.g. water); water is a polar molecule (dipole).","Ion: an atom or group that has lost electrons (cation, positive) or gained electrons (anion, negative); electrolytes dissociate into ions in water.","Electron theory: electric current in metals is a drift of free electrons; in electrolytes and body fluids it is movement of ions."]},
    {h:"Conductors, insulators and semiconductors", p:["Conductors: many free electrons (copper, silver, aluminium) or free ions (saline, tissue fluid).","Insulators: electrons tightly bound (rubber, glass, plastic, dry wood); used on leads, handles and floor mats.","Semiconductors: intermediate (silicon, germanium); conductivity changed by doping and temperature; basis of diodes and transistors.","Tissues: blood and muscle (high water and ion content) conduct well; fat, bone and dry skin conduct poorly."]},
    {h:"Physiotherapy relevance", p:["Explains iontophoresis (ion movement), electrolysis under DC electrodes and why polar water molecules heat in SWD and microwave fields.","Guides safety: metal conducts heat and current, rubber and dry wood insulate; wet floors and hands increase shock risk."]},
    {h:"Conclusion", p:["Knowledge of matter, atoms, molecules and ions is the foundation for understanding how currents, heat and water act on the body and for using physical modalities safely."]}
  ],
  tip:"Draw a Bohr model of a sodium atom (11 protons, 12 neutrons, electrons 2, 8, 1) and show it losing one electron to become Na+, beside chlorine gaining one to become Cl-. Add a small table: conductor, insulator, semiconductor with examples.",
  evidence:[["Physical principles of matter","Established physics underpinning modality use","Established science"]],
  evidenceSource:"Standard physics texts for physiotherapy; Forster and Palastanga, Clayton's Electrotherapy (physics chapters)",
  outcomes:[["Understanding demonstrated in viva","Ability to explain modality physics"]],
  recent:["Modern electrotherapy texts present physics alongside clinical reasoning, linking tissue properties (water, ion and fat content) directly to how each modality deposits energy."],
  mnemonic:{word:"PEN", items:[["P","Proton: positive, in nucleus"],["E","Electron: negative, in shells"],["N","Neutron: neutral, in nucleus"]], extra:"Cation is pawsitive (+); anion is negative."},
  example:"A student in Thanjavur explains to a patient why wax at 50 degrees C feels bearable but water at the same temperature would scald: wax has lower specific heat and conductivity and releases latent heat slowly.",
  flags:["Metal objects in heat or current fields concentrate energy","Wet skin, floor or hands greatly lower resistance and raise shock risk"],
  viva:[["What is an ion?","An atom or group of atoms that has gained or lost electrons and so carries a charge."],["Why does tissue conduct electricity?","Tissue fluids contain free ions such as Na+, K+ and Cl- that carry charge."],["Give two insulators used in physiotherapy equipment.","Rubber and plastic (PVC) on leads and handles."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Physical principles: matter and electricity."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Physical principles."},{b:"guyton", ch:"Transport of substances through cell membranes"}],
  keywords:"properties of matter states density specific heat latent heat atom proton electron neutron molecule ion ionic covalent conductor insulator semiconductor electron theory",
  mcq:[["A cation is an ion that has:",["Gained electrons and is negative","Lost electrons and is positive","Gained neutrons","Lost protons"],1,"Losing electrons leaves a net positive charge."],["Which material is a semiconductor?",["Copper","Rubber","Saline","Silicon"],3,"Silicon and germanium are the common semiconductors."]]
},
{
  id:"el-static-current-electricity", title:"Static and current electricity; electrical units", subject:"Electrotherapy", region:"Biophysics", stages:"steps",
  aliases:["static electricity","current electricity","electrical units","coulomb volt ampere ohm","potential difference","electromotive force","electroscope"],
  simple:"Static electricity is charge that stays on a surface, such as when you rub a comb. Current electricity is charge that flows steadily through a conductor, driven by a voltage from a cell or mains supply. Each quantity has a unit: charge in coulombs, voltage in volts, current in amperes, resistance in ohms and power in watts.",
  flow:["Charges: positive and negative; like repel, unlike attract","Static: charge held at rest on a body","Charging by friction, conduction or induction","Current: steady flow of charge in a circuit","Driven by EMF from a cell or generator","Measured in coulomb, volt, ampere, ohm, watt"],
  exam:[
    {h:"Static electricity", p:["Accumulation of electric charge at rest on the surface of a body, usually an insulator.","Charging by friction (rubbing removes electrons from one body to another), by conduction (contact with a charged body) and by induction (bringing a charged body near, then earthing).","Laws: like charges repel, unlike attract; Coulomb's law: force is proportional to the product of charges and inversely proportional to the square of the distance.","Charge collects at sharp points (point discharge, lightning conductor); gold-leaf electroscope detects charge."]},
    {h:"Electric field and potential", p:["Electric field: region around a charge where another charge feels a force.","Potential: work done to bring unit positive charge from infinity to a point; potential difference (PD) between two points drives current.","Electromotive force (EMF): energy given per unit charge by a source (cell, generator); some is lost inside the source due to internal resistance."]},
    {h:"Current electricity", p:["Steady flow of charge through a closed conducting circuit; in metals by free electrons, in electrolytes by ions.","Conventional current flows from positive to negative; electron flow is in the opposite direction.","Sources: primary and secondary (rechargeable) cells, batteries, generators and mains supply; direct current (DC) flows one way, alternating current (AC) reverses periodically.","Effects of current: heating (Joule), chemical (electrolysis), magnetic and physiological (nerve and muscle stimulation)."]},
    {h:"Electrical units", p:["Charge: coulomb (C).","Current: ampere (A) = 1 coulomb per second; therapy uses milliamperes (mA) and microamperes.","Potential difference and EMF: volt (V) = 1 joule per coulomb.","Resistance: ohm; Ohm's law V = I x R. Impedance (AC resistance including capacitance and inductance) is also measured in ohms.","Power: watt (W) = V x I = I squared x R; energy: joule (J) = watt x second; commercial unit kilowatt-hour (the 'unit' on electricity bills).","Capacitance: farad (F); inductance: henry (H); frequency: hertz (Hz); charge density and current density (mA/cm2)."]},
    {h:"Measuring instruments", p:["Galvanometer: detects small currents; ammeter (in series, low resistance) measures current; voltmeter (in parallel, high resistance) measures PD; milliammeter on stimulators shows treatment current.","Multimeter: measures V, A and ohms; used in basic equipment checks such as lead continuity."]},
    {h:"Physiotherapy relevance", p:["Static charge can damage electronic circuits and may give small shocks from synthetic sheets and dry air.","Dose of iontophoresis (mA-min) and safety limits (current density, leakage current in microamperes) depend on these units."]},
    {h:"Conclusion", p:["Clear understanding of static and current electricity and their units allows safe setting of treatment doses and correct reading of meters and safety specifications."]}
  ],
  tip:"Draw a simple circuit: cell, switch, ammeter in series, resistor and voltmeter in parallel across it, with arrows for conventional current. Beside it write a units table: quantity, unit, symbol.",
  evidence:[["Basic laws of electricity","Established physics","Established science"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy (physics chapters)",
  outcomes:[["Correct meter reading and dose calculation","Practical competence"]],
  recent:["Since 2019 the SI system defines the ampere by fixing the value of the elementary charge, rather than by the force between wires."],
  mnemonic:{word:"CVARW", items:[["C","Coulomb: charge"],["V","Volt: push"],["A","Ampere: flow"],["R","Ohm: resistance"],["W","Watt: power = V x I"]], extra:"Ammeter in series, voltmeter in parallel."},
  example:"In a Tirunelveli hostel, a student gets a small spark touching a metal door after walking on a nylon carpet: static charge built up by friction discharging to earth.",
  flags:["Connecting an ammeter in parallel can damage it and the circuit","Static discharge can damage sensitive electronic boards during repairs"],
  viva:[["Define one ampere.","A current of one coulomb of charge per second."],["What is EMF?","The energy supplied by a source per unit charge, measured in volts."],["What is the commercial unit of electrical energy?","The kilowatt-hour (one unit)."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: Static electricity; Current electricity."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Physical principles of electricity."}],
  keywords:"static electricity charging friction induction Coulomb law current electricity EMF potential difference units coulomb volt ampere ohm watt joule farad henry hertz ammeter voltmeter",
  mcq:[["A voltmeter is connected:",["In series with the load","Between live and earth only","In parallel across the load","Inside the fuse"],2,"A voltmeter measures PD across a component, so it goes in parallel."],["The unit of electrical power is:",["Watt","Coulomb","Joule","Henry"],0,"Power = V x I, measured in watts."]]
},
{
  id:"el-condensers-ac-ohm-fuses", title:"Condensers, alternating current, magnetism, Ohm's law and fuses", subject:"Electrotherapy", region:"Biophysics", stages:"steps",
  aliases:["condenser","capacitor","alternating current","RMS value","magnetism","electromagnet","Ohm's law","fuse","MCB"],
  simple:"A condenser (capacitor) stores charge on two plates separated by an insulator; it blocks steady DC but lets AC pass. Alternating current keeps changing direction, 50 times a second in Indian mains. Ohm's law links voltage, current and resistance, and a fuse is a weak link that melts to cut the circuit if too much current flows.",
  flow:["Capacitor: two plates and a dielectric store charge","Blocks DC, passes AC; reactance falls with frequency","AC: sine wave, 230 V RMS, 50 Hz in India","Current produces magnetic field; magnets induce current","Ohm's law: V = I x R","Fuse melts when current exceeds its rating"],
  exam:[
    {h:"Condenser (capacitor)", p:["Two conductors (plates) separated by an insulator (dielectric: air, paper, mica, ceramic).","Capacitance C = Q / V, unit farad (usually microfarad); increases with plate area and dielectric constant, decreases with plate separation.","Charges and discharges through a resistor exponentially; time constant = R x C.","Capacitive reactance Xc = 1 / (2 pi f C): blocks DC, passes AC better at higher frequency (why skin impedance falls with medium frequency currents).","Uses: smoothing rectified DC, timing circuits in stimulators, tuning circuits in SWD; in SWD condenser field method the body acts as part of the dielectric."]},
    {h:"Alternating current", p:["Current that reverses direction periodically, usually sinusoidal; produced by a generator (dynamo) by electromagnetic induction.","Terms: cycle, frequency (Hz), period, peak value, peak-to-peak and RMS (effective) value; RMS = peak / square root of 2 (about 0.707 x peak).","Indian mains: about 230 V RMS (peak about 325 V), 50 Hz, single phase for domestic and clinic supply; three phase (about 400-415 V) for large loads.","Advantages: easily transformed up or down; easily rectified to DC for equipment."]},
    {h:"Magnetism", p:["Magnets have north and south poles; like poles repel; magnetic field shown by lines of force.","A current-carrying conductor produces a magnetic field (Oersted); a coil (solenoid) with an iron core forms an electromagnet, used in relays, switches and circuit breakers.","A changing magnetic field induces EMF in a nearby conductor (Faraday); basis of transformers, induction coils and the inductive (cable) method of SWD.","Magnetic field strength unit: tesla (MRI scanners use about 1.5-3 T; pacemaker patients must avoid strong fields)."]},
    {h:"Ohm's law and resistances", p:["At constant temperature, current through a conductor is proportional to the potential difference: V = I x R.","Series resistors: R = R1 + R2 + ...; same current, voltage divides. Parallel: 1/R = 1/R1 + 1/R2 + ...; same voltage, current divides.","Resistance depends on material (resistivity), length (directly) and cross-sectional area (inversely) and temperature.","Applied: dry skin has high resistance, so a constant-voltage stimulator gives less current; wetting the skin lowers resistance and current rises suddenly (risk), so constant-current stimulators are safer for many uses. Rheostat and potentiometer control current and voltage."]},
    {h:"Fuses and circuit protection", p:["Fuse: a short thin wire of low melting point alloy (tin-lead or tinned copper) in a holder, placed in the live wire, which melts when current exceeds its rating, breaking the circuit.","Rating chosen slightly above normal working current of the appliance (e.g. 3 A, 5 A, 13 A); never replace with a thicker wire or higher rating.","Types: rewireable (kit-kat), cartridge, glass fuses inside equipment.","Miniature circuit breaker (MCB) trips on overcurrent and can be reset; residual current circuit breaker (RCCB or ELCB) trips when leakage to earth is detected (e.g. 30 mA), protecting people against shock."]},
    {h:"Conclusion", p:["Condensers, AC, magnetism and Ohm's law explain how electrotherapy machines work, and fuses and circuit breakers are the first line of protection against fire and electric shock."]}
  ],
  tip:"Draw a sine wave with peak, RMS and one cycle marked (20 ms at 50 Hz). Beside it draw a capacitor symbol with plates and dielectric, and a plug with the fuse in the live wire.",
  evidence:[["RCD (30 mA) protection","Reduces risk of fatal electric shock in wet environments","Established safety standard"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy; IEC and national wiring regulations",
  outcomes:[["Fuse and circuit breaker checks","Equipment and wiring safety"]],
  recent:["Indian wiring practice increasingly requires residual current devices (RCCB, commonly 30 mA) on circuits in homes and clinics, especially in wet areas."],
  mnemonic:{word:"VIR triangle", items:[["V","Top of triangle"],["I x R","Bottom; cover the one you want"],["Fuse","In the live wire, rating just above normal"]], extra:"Capacitor: blocks DC, passes AC."},
  example:"A stimulator in a Kumbakonam clinic keeps blowing its 1 A glass fuse; instead of fitting a thicker wire, the therapist tags it 'do not use' and sends it to the biomedical engineer, who finds a shorted capacitor.",
  flags:["Replacing a fuse with wire or a higher rating removes protection","Fuse placed in the neutral leaves the appliance live when it blows","Constant-voltage output with suddenly wetted skin causes current surge"],
  viva:[["State Ohm's law.","At constant temperature, current is proportional to potential difference: V = I x R."],["What is RMS value of AC?","The equivalent DC value producing the same heating; peak divided by root 2."],["Why does a capacitor pass AC but not DC?","Its reactance falls with frequency; at zero frequency (DC) reactance is infinite once charged."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: Condensers; Alternating current; Magnetism; Fuses."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Physical principles of electricity."}],
  keywords:"condenser capacitor capacitance farad reactance alternating current RMS 230 V 50 Hz magnetism electromagnet Ohm law series parallel fuse MCB RCCB",
  mcq:[["The RMS value of a sinusoidal AC with peak 325 V is about:",["162 V","460 V","325 V","230 V"],3,"RMS = peak / 1.414, about 230 V."],["A fuse should be placed in the:",["Earth wire","Live wire","Neutral wire","Patient lead"],1,"In the live wire, so the appliance is disconnected from the supply when it blows."]]
},
{
  id:"el-valves-semiconductors", title:"Valves, semiconductors, transistors, transformers and chokes", subject:"Electrotherapy", region:"Biophysics", stages:"steps",
  aliases:["thermionic valve","diode","rectifier","semiconductor","transistor","transformer","choke coil","inductor"],
  simple:"Inside electrotherapy machines, electronic parts shape the current. Valves and semiconductor diodes let current flow one way only, turning AC into DC. Transistors switch and amplify currents. Transformers change voltage up or down, and chokes (coils) resist changes in current and smooth it.",
  flow:["Mains AC enters the machine","Transformer changes voltage and isolates patient","Diodes (or valves) rectify AC to DC","Capacitors and chokes smooth the DC","Transistors switch and amplify to shape pulses","Output control sets the treatment current"],
  exam:[
    {h:"Thermionic valves", p:["Evacuated glass tube with a heated cathode that emits electrons (thermionic emission) and an anode (plate).","Diode valve: current flows only when the anode is positive: rectification.","Triode: a grid between cathode and anode controls electron flow: amplification and oscillation; used in old SWD oscillator circuits.","Largely replaced by semiconductors (smaller, cooler, robust), though high-power valves were long used in diathermy machines."]},
    {h:"Semiconductors and diodes", p:["Pure silicon or germanium conducts poorly; doping adds free electrons (n-type) or holes (p-type).","p-n junction diode: conducts in forward bias, blocks in reverse bias.","Half-wave rectification (one diode) and full-wave rectification (two diodes with centre-tap or four-diode bridge); output smoothed by capacitor and choke.","Other devices: Zener diode (voltage regulation), LED (indicators), thyristor (power control)."]},
    {h:"Transistors", p:["Three-layer semiconductor (NPN or PNP) with emitter, base and collector; field-effect transistors (FETs) are also widely used.","A small base current controls a large collector current: amplifier (EMG and biofeedback amplifiers) and electronic switch.","Arranged as oscillators and multivibrators to produce pulses of set duration and frequency in TENS, NMES and IDC units; integrated circuits and microprocessors combine many transistors."]},
    {h:"Transformers", p:["Two coils (primary and secondary) wound on a laminated soft iron core; works only with AC by mutual electromagnetic induction.","Voltage ratio: Vs / Vp = Ns / Np; step-up (more secondary turns) or step-down (fewer turns); power is nearly conserved, so current changes inversely.","Laminated core reduces eddy current losses; losses also from hysteresis and copper resistance.","Isolation transformer: separates the patient circuit from mains earth, an important safety feature; old faradic coils were induction coils (a type of transformer with an interrupter)."]},
    {h:"Chokes (inductors)", p:["A coil of wire, often on an iron core, which opposes changes in current by self-induction; inductive reactance XL = 2 pi f L rises with frequency.","Uses: smoothing rectified DC (choke-input filter), limiting current in fluorescent lamps, and tuning circuits (with capacitors) in SWD to resonance: f = 1 / (2 pi square root of LC).","A choke controls AC with little heat loss compared with a resistor."]},
    {h:"Application: block diagram of a stimulator", p:["Mains, fuse and switch, step-down isolation transformer, rectifier, smoothing (capacitor and choke), voltage regulator, oscillator or microprocessor (pulse timing), output amplifier, intensity control, patient terminals.","Battery TENS units skip the transformer and rectifier but use transistor oscillators and a step-up output stage."]},
    {h:"Conclusion", p:["Rectifiers, transistors, transformers and chokes turn mains AC into the safe, shaped currents used in therapy; knowing them helps the physiotherapist understand faults and safety features."]}
  ],
  tip:"Draw a block diagram of a mains-operated stimulator (transformer, rectifier, smoothing, oscillator, amplifier, intensity control, electrodes). Beside it draw a transformer with primary and secondary coils and write Vs/Vp = Ns/Np, and a bridge rectifier with input and output waveforms.",
  evidence:[["Electronic component principles","Established physics and engineering","Established science"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy (electronics chapters)",
  outcomes:[["Fault recognition in viva and practicals","Understanding of equipment"]],
  recent:["Modern stimulators are microprocessor controlled with digital displays and software-set waveforms, replacing analogue valve and discrete transistor circuits."],
  mnemonic:{word:"TRSO", items:[["T","Transformer: change and isolate voltage"],["R","Rectifier: AC to DC"],["S","Smoothing: capacitor and choke"],["O","Oscillator: transistors shape pulses"]], extra:"Transformers work only with AC."},
  example:"During a practical in Chennai, the examiner asks a student to explain why an old valve-type SWD needs warming up: the cathode heater must reach temperature before thermionic emission begins.",
  flags:["Opening equipment casing exposes high-voltage capacitors that stay charged","Transformer hum, burning smell or overheating means remove from use"],
  viva:[["What does a rectifier do?","Converts AC to DC by letting current flow in one direction only."],["What is the turns ratio rule of a transformer?","Vs/Vp = Ns/Np."],["Why is a transformer core laminated?","To reduce eddy current losses and heating."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: Thermionic valves; Semiconductors; Transformers."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Physical principles of electricity."}],
  keywords:"thermionic valve diode triode semiconductor p-n junction rectifier half wave full wave bridge transistor amplifier oscillator transformer step up step down choke inductor reactance",
  mcq:[["A transformer cannot work with DC because:",["Induction needs a changing magnetic field","DC is too high voltage","DC melts the core","Transformers need diodes"],0,"Only a changing current produces a changing flux to induce EMF."],["A choke is mainly used to:",["Store heat","Convert DC to AC","Oppose changes in current and smooth DC","Measure voltage"],2,"Its self-inductance opposes changes, smoothing current."]]
},
{
  id:"el-chemical-em-spectrum", title:"Chemical effects of current, electromagnetic induction and the electromagnetic spectrum", subject:"Electrotherapy", region:"Biophysics", stages:"steps",
  aliases:["electrolysis","Faraday's laws","chemical effects of current","electromagnetic induction","Lenz's law","electromagnetic spectrum","laws of radiation"],
  simple:"Direct current passing through salt solutions splits them: acid forms at the positive electrode and alkali at the negative one, which is why DC can burn skin. A changing magnetic field makes a current in a nearby wire (electromagnetic induction), the basis of transformers and SWD. The electromagnetic spectrum lines up radio waves, short wave, microwave, infrared, light, UV and X-rays by wavelength.",
  flow:["DC through electrolyte causes electrolysis","Anode: acid; cathode: alkali and gas","Changing magnetic field induces EMF (Faraday)","Induced current opposes the change (Lenz)","EM waves: c = frequency x wavelength","Therapy uses SWD, microwave, IR, visible and UV bands"],
  exam:[
    {h:"Chemical effects of current (electrolysis)", p:["When DC passes through an electrolyte, ions migrate: cations to the cathode, anions to the anode, and chemical changes occur at the electrodes.","In tissue fluid (NaCl in water): at the cathode sodium reacts with water to form sodium hydroxide (alkali) and hydrogen gas; at the anode chlorine forms hydrochloric acid and oxygen is released.","Faraday's first law: mass of substance liberated is proportional to the quantity of charge passed (current x time); second law: for the same charge, mass is proportional to the chemical equivalent.","Applications: iontophoresis, electrolysis for hair removal; danger: chemical burns under DC, IDC, diadynamic and poorly balanced monophasic currents; corrosion of metal electrodes."]},
    {h:"Electromagnetic induction", p:["Faraday's law: an EMF is induced in a conductor when the magnetic flux through it changes; size depends on rate of change of flux.","Lenz's law: the induced current flows in a direction that opposes the change producing it.","Self-induction (a coil opposing changes in its own current: chokes) and mutual induction (one coil inducing current in another: transformers, induction coil for faradic current).","Eddy currents: induced circulating currents in conductors; used in SWD inductive (cable or drum) method to heat tissue, and the reason metal in the field overheats."]},
    {h:"Electromagnetic waves and the spectrum", p:["EM waves are oscillating electric and magnetic fields travelling at 3 x 10^8 m/s in vacuum; c = frequency x wavelength; they need no medium.","Order of increasing frequency (decreasing wavelength): radio waves (including SWD 27.12 MHz, 11 m), microwaves (2450 MHz, 12.25 cm), infrared (about 770 nm - 1 mm; therapeutic near IR 770-1500 nm and far IR 1500-15000 nm), visible light (about 400-770 nm), ultraviolet (UVA 315-400 nm, UVB 280-315 nm, UVC 100-280 nm), X-rays and gamma rays.","Ionising radiation (X-ray, gamma, short UV) can break chemical bonds; therapeutic bands below UV are non-ionising."]},
    {h:"Laws governing radiation", p:["Inverse square law: intensity falls with the square of distance from a point source (doubling distance gives one quarter intensity), important in IR and UV dosage.","Cosine law: intensity is greatest when rays strike the surface at right angles; it varies with the cosine of the angle of incidence.","Grotthus-Draper law: only absorbed radiation produces an effect; penetration depends on wavelength and tissue.","Reflection, refraction and absorption govern how much energy reaches tissue."]},
    {h:"Physiotherapy relevance", p:["Choose and position lamps and applicators using the inverse square and cosine laws.","Know which bands heat (SWD, microwave, IR) and which cause photochemical effects (UV).","Use DC chemical effects deliberately (iontophoresis) while preventing burns with low current density and thick pads."]},
    {h:"Conclusion", p:["Electrolysis, electromagnetic induction and the EM spectrum explain the action and hazards of DC, SWD, microwave, IR and UV, and guide safe dosage."]}
  ],
  tip:"Draw a horizontal spectrum bar from radio to gamma with arrows for increasing frequency and decreasing wavelength, and mark SWD, microwave, IR, visible and UVA/B/C positions. Below it draw a beaker of saline with anode (HCl, O2) and cathode (NaOH, H2).",
  evidence:[["Inverse square and cosine laws in lamp dosage","Predict skin irradiance accurately","Established physics"]],
  evidenceSource:"Forster and Palastanga, Clayton's Electrotherapy; Robertson et al., Electrotherapy Explained",
  outcomes:[["Dosage calculation for lamps","Correct application of radiation laws"]],
  recent:["Photobiomodulation research now standardises reporting of wavelength, irradiance and energy density so that light therapy doses can be compared across studies."],
  mnemonic:{word:"Raging Martians Invaded Venus Using X-ray Guns", items:[["R M","Radio (SWD), Microwave"],["I V","Infrared, Visible"],["U X G","Ultraviolet, X-ray, Gamma"]], extra:"Cathode makes NaOH (alkali); anode makes HCl (acid)."},
  example:"A lamp at 50 cm gives comfortable warmth; when a student in Salem moves it to 25 cm, the intensity becomes about four times greater, illustrating the inverse square law and the risk of burns.",
  flags:["Chemical burns from DC under small or dry electrodes","Metal in SWD or microwave fields heats by eddy currents","Eyes must be protected from UV and intense IR"],
  viva:[["What forms under the cathode during electrolysis of saline?","Sodium hydroxide (alkali) and hydrogen gas."],["State Lenz's law.","The induced current opposes the change in flux that produces it."],["What is the wavelength of SWD at 27.12 MHz?","About 11 metres."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: Chemical effects of current; Electromagnetic induction; Electromagnetic spectrum."},{c:"Robertson V, Ward A, Low J, Reed A. Electrotherapy Explained: Principles and Practice. 4th ed. Chapter: Electromagnetic radiation."},{b:"cameron", ch:"Electromagnetic waves: diathermy, light and ultraviolet"}],
  keywords:"electrolysis Faraday laws chemical effects anode acid cathode alkali electromagnetic induction Lenz eddy currents electromagnetic spectrum inverse square law cosine law Grotthus Draper",
  mcq:[["Doubling the distance of an IR lamp from the skin makes intensity:",["Double","One quarter","Half","Unchanged"],1,"Inverse square law: intensity varies with 1/distance squared."],["Which law states the induced current opposes the change producing it?",["Ohm's law","Joule's law","Coulomb's law","Lenz's law"],3,"Lenz's law describes the direction of induced current."]]
},
{
  id:"el-mains-shock-earthing", title:"Mains supply, short circuit, electric shock and earthing", subject:"Electrotherapy", region:"Electrical safety", stages:"steps",
  aliases:["mains supply","earthing","short circuit","electric shock","macroshock microshock","leakage current","three pin plug","earth leakage"],
  simple:"Mains electricity in India is about 230 V AC at 50 Hz, carried by live, neutral and earth wires. A short circuit lets a huge current flow and can cause fire, which fuses prevent. If a person becomes part of a circuit to earth, current passes through them: an electric shock. Earthing gives faulty current an easy path to ground so the fuse blows instead.",
  flow:["Supply: live, neutral, earth at 230 V, 50 Hz","Short circuit: very low resistance, huge current","Fuse or MCB cuts the supply","Shock: body completes a path to earth","Effect depends on current, path, time","Earthing and RCD divert fault current and trip"],
  exam:[
    {h:"Mains supply", p:["Generated as three-phase AC at the power station, stepped up for transmission and stepped down at local substations; domestic and clinic supply in India is single-phase about 230 V, 50 Hz.","Three conductors: live (phase, red or brown) at high potential, neutral (black or blue) near earth potential, and earth (green or green-yellow) connected to the ground through an earth electrode.","Distribution board: main switch, MCBs for each circuit, RCCB/ELCB for earth leakage; three-pin plugs with the larger earth pin, switched sockets; fuse and switch always in the live wire."]},
    {h:"Short circuit", p:["Direct contact of live and neutral (or live and earth) with very low resistance, so current becomes very large (I = V / R).","Causes: damaged insulation, loose wires, water entering equipment, overloaded sockets.","Effects: sparks, overheating, fire and damage; protection by correctly rated fuses and MCBs that open the circuit."]},
    {h:"Electric shock", p:["Occurs when current passes through the body, which becomes part of a circuit, usually between a live part and earth (earth shock) or between live and neutral.","Approximate effects of 50 Hz current hand to hand or hand to foot for about 1 s: about 1 mA perception; about 10-16 mA 'let-go' threshold (cannot release grip); about 20-50 mA respiratory muscle paralysis and severe pain; about 75-100 mA and above ventricular fibrillation; several amperes: cardiac standstill and burns.","Microshock: very small currents (tens of microamperes) applied directly to the heart (e.g. via a catheter or pacing wire) can cause fibrillation.","Factors: current size, path (across the chest most dangerous), duration, frequency (50-60 Hz most dangerous; high frequency mainly heats), skin resistance (dry skin about 100 kilo-ohm, wet skin about 1 kilo-ohm), body weight and health."]},
    {h:"Earthing", p:["Metal casing of Class I equipment is connected through the earth pin to a buried earth electrode (plate or pipe in moist soil, often with salt and charcoal).","If a live wire touches the case, current flows through the low-resistance earth path, so a large fault current blows the fuse or trips the MCB; the case does not stay live.","Earth must be low resistance and continuous; an RCCB (commonly 30 mA trip) senses imbalance between live and neutral and cuts the supply in milliseconds.","Earth-free (isolated) supplies, Class II double insulation and battery units are alternatives; in some electrotherapy, isolating the patient circuit from earth prevents the patient becoming a path to earth."]},
    {h:"Electrical safety checks for physiotherapy departments", p:["Daily user checks: plugs, cables, insulation, switches, lamps and indicators; no cracked cases; intensity controls at zero on starting.","Periodic tests by a biomedical engineer (commonly yearly and after repairs): earth (protective earth) continuity and resistance (very low, typically under about 0.2-0.3 ohm), insulation resistance, and leakage current measurement (earth, enclosure and patient leakage) against IEC 60601-1 limits, e.g. patient leakage about 100 microamperes for type B and BF parts and 10 microamperes for type CF in normal condition.","Calibration of output: meters, timers and output (e.g. ultrasound output with a radiation force balance, stimulator pulse width and frequency on an oscilloscope); label and date-tag tested equipment; keep a log.","Environment: no water near equipment, no multi-plug adaptors or extension cords chained, wooden or insulated couches, dry floors, SWD at a distance from other stimulators."]},
    {h:"Conclusion", p:["Understanding mains supply, short circuits and shock thresholds, and maintaining earthing, RCD protection, leakage testing and calibration keeps both patients and therapists safe."]}
  ],
  tip:"Draw a three-pin plug with live (fuse), neutral and earth wires to an appliance with a metal case; show a fault (live touching case) with arrows running to the earth electrode and the fuse blowing. Add a small table of current versus effect (1, 10, 50, 100 mA).",
  evidence:[["RCD protection in wet areas","Reduces fatal shocks","Established safety standard"],["Periodic electrical safety testing (IEC 62353)","Detects earth and leakage faults before harm","Established safety standard"]],
  evidenceSource:"IEC 60601-1 (medical electrical equipment safety) and IEC 62353 (recurrent testing); Forster and Palastanga, Clayton's Electrotherapy",
  outcomes:[["Earth continuity resistance","Integrity of protective earth"],["Leakage current in microamperes","Risk of shock to patient or user"],["Calibration record","Accuracy of delivered dose"]],
  recent:["IEC 62353 provides a standard method for routine and after-repair testing of medical electrical equipment, widely used by hospital biomedical departments."],
  mnemonic:{word:"1-10-50-100", items:[["1 mA","Felt"],["10 mA","Cannot let go"],["50 mA","Breathing muscles fail, severe pain"],["100 mA","Ventricular fibrillation"]], extra:"Earth: green; fuse: in live; RCCB trips at about 30 mA leakage."},
  example:"In a Madurai clinic, a therapist feels a tingle touching the metal casing of an old IFT machine; it is taken out of use, and testing finds a broken earth wire inside the plug.",
  flags:["Tingling from equipment casing: remove from use immediately","Broken plugs, exposed wires or missing earth pin","Water or wet floors near mains equipment","Multi-plug adaptors and long extension leads"],
  viva:[["Why is earthing needed?","To provide a low-resistance path for fault current so the fuse blows and the casing does not stay live."],["What is the let-go current?","About 10-16 mA at 50 Hz, above which a person cannot release the grip."],["What is microshock?","Fibrillation from tiny currents (microamperes) applied directly to the heart."]],
  refs:[{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapters: The mains supply; Electric shock; Earthing."},{c:"International Electrotechnical Commission. IEC 60601-1 Medical electrical equipment - General requirements for basic safety and essential performance; IEC 62353 Recurrent test and test after repair of medical electrical equipment."},{b:"cameron", ch:"Electrical safety in electrotherapy"}],
  keywords:"mains supply 230 V 50 Hz live neutral earth short circuit electric shock let-go current ventricular fibrillation microshock earthing RCCB ELCB leakage current IEC 60601 calibration",
  mcq:[["The earth wire's purpose in Class I equipment is to:",["Carry the normal working current","Reduce the voltage to 110 V","Provide a low-resistance path for fault current","Supply the patient circuit"],2,"Fault current flows to earth and blows the fuse, so the case does not stay live."],["A current of about 100 mA at 50 Hz across the chest is likely to cause:",["Ventricular fibrillation","Only perception","No effect","Mild warmth only"],0,"Around 75-100 mA and above can trigger ventricular fibrillation."]]
},
{
  id:"el-electric-shock-first-aid", title:"First aid for electric shock", subject:"Electrotherapy", region:"Emergency care", stages:"steps",
  aliases:["electric shock first aid","electrocution management","CPR after shock","electrical burns","rescue from live wire","safety in electrotherapy department"],
  simple:"If someone gets an electric shock, first switch off the power without touching them. Then check if they respond and breathe, call for help (108 or 112 in India), start CPR if needed and use an AED. Electrical burns can be deeper than they look, so every shock victim with symptoms needs medical review.",
  flow:["Do not touch: switch off at mains or unplug","If not possible, push away with dry insulator","Check response and breathing; call 108 or 112","No normal breathing: CPR 30:2 and AED","Breathing: recovery position, treat burns, monitor","Refer for ECG; report and tag faulty equipment"],
  exam:[
    {h:"Immediate safety", p:["Do not touch the victim while they are still in contact with the current.","Switch off at the mains switch or MCB, or pull out the plug; in an electrotherapy department, turn the machine and the wall switch off.","If the supply cannot be switched off (low voltage), stand on dry insulating material (rubber mat, dry wood, newspapers) and separate the victim from the source with a dry wooden stick, plastic chair or rolled dry cloth; never use metal or wet objects.","High voltage lines: keep away (at least several metres) and call the electricity board and emergency services."]},
    {h:"Assessment (DRSABC)", p:["Danger cleared, check Response (tap and shout), Send for help: call 108 (ambulance) or 112 (national emergency number) and ask for an AED.","Open the Airway (head tilt-chin lift; jaw thrust if spinal injury suspected after a fall), check Breathing for no more than 10 seconds."]},
    {h:"Cardiopulmonary resuscitation", p:["If not breathing normally: start chest compressions at the centre of the chest, 100-120 per minute, depth about 5-6 cm in adults, full recoil; 30 compressions to 2 rescue breaths (or compression-only CPR if untrained or unwilling).","Attach an AED as soon as available and follow prompts; ventricular fibrillation is common after electric shock and needs early defibrillation.","Continue until the person breathes normally, professional help takes over, or the rescuer is exhausted."]},
    {h:"If breathing and conscious or unconscious with breathing", p:["Unconscious but breathing: place in the recovery position (unless spinal injury suspected) and monitor breathing.","Treat burns: cool with clean running water for about 20 minutes, remove rings and watches before swelling, cover loosely with cling film or a clean non-fluffy dressing; do not apply ice, toothpaste, oil or butter (common Indian home remedies).","Look for entry and exit wounds, fractures or spinal injury from falls or violent muscle contraction, and treat for shock (lay flat, keep warm, raise legs if no injury)."]},
    {h:"Medical referral and follow up", p:["All patients who lost consciousness, have burns, abnormal heart rhythm, chest pain, or a high-voltage or across-chest shock need hospital assessment with an ECG; arrhythmias and myoglobinuria from muscle damage may develop.","Minor low-voltage shocks with no symptoms still need observation and advice to return if palpitations or chest pain develop."]},
    {h:"After the incident in a physiotherapy department", p:["Isolate and label the faulty equipment 'Do not use'; do not attempt repair; inform the biomedical engineer.","Complete an incident report, inform the patient and supervisor, and review safety checks (earthing, leakage, cables, RCD testing).","Prevention: regular safety testing, dry environment, staff training in basic life support and the location of the AED and mains switches."]},
    {h:"Conclusion", p:["Safe rescue (switch off first), early CPR and defibrillation, proper burn care and ECG assessment save lives after electric shock; prevention by equipment maintenance is the physiotherapist's responsibility."]}
  ],
  tip:"Draw a flowchart: Switch off or separate with dry wood, then Response?, then Call 108/112 and get AED, then Breathing? Yes: recovery position and burns care; No: CPR 30:2 and AED. End box: ECG, report, tag equipment.",
  evidence:[["Early CPR and defibrillation in cardiac arrest","Improves survival","High (resuscitation guidelines)"],["Cooling burns with running water for 20 minutes","Reduces burn depth and pain","Moderate"]],
  evidenceSource:"ILCOR and AHA guidelines for CPR and emergency cardiovascular care (2020 onwards); first aid guidance from national resuscitation councils",
  outcomes:[["Return of spontaneous circulation","Success of resuscitation"],["ECG","Detection of arrhythmia after shock"],["Burn depth and area","Severity of electrical burns"]],
  recent:["The 2020 AHA and ILCOR guidelines continue to stress high-quality compressions (100-120 per minute, 5-6 cm depth) and early AED use by bystanders."],
  mnemonic:{word:"SAFE", items:[["S","Switch off or separate with insulator"],["A","Assess response and breathing"],["F","Fetch help: 108/112 and AED"],["E","Effective CPR 30:2 and ECG later"]], extra:"Never touch a victim still in contact with live current."},
  example:"In a college physiotherapy department in Vellore, a cleaner touches a frayed wire near a wet floor and collapses; a student switches off the MCB, checks breathing, starts CPR and uses the AED while a colleague calls 108.",
  flags:["Victim still in contact with live current","Unconscious or not breathing normally","Chest pain, palpitations or burns after shock","High-voltage injury or fall from height"],
  viva:[["What is the first step in electric shock first aid?","Ensure safety: switch off the supply or separate the victim with a dry insulator without touching them."],["What is the compression rate in adult CPR?","100-120 per minute, depth about 5-6 cm, ratio 30:2."],["Why is an ECG needed after electric shock?","Arrhythmias such as ventricular fibrillation or conduction defects can occur or develop later."]],
  refs:[{c:"Panchal AR, Bartos JA, Cabanas JG, et al. Part 3: Adult basic and advanced life support: 2020 American Heart Association Guidelines for Cardiopulmonary Resuscitation and Emergency Cardiovascular Care. Circulation. 2020;142(16 suppl 2):S366-S468.", q:"Panchal 2020 AHA adult basic advanced life support guidelines"},{c:"Forster A, Palastanga N. Clayton's Electrotherapy: Theory and Practice. Chapter: Electric shock and its treatment."},{c:"Park K. Textbook of Preventive and Social Medicine. Chapter: Accidents and injuries."}],
  keywords:"electric shock first aid switch off insulator DRSABC CPR 30:2 AED defibrillation recovery position electrical burns cooling ECG incident report 108 112",
  mcq:[["The first action on finding a person in contact with a live wire is to:",["Pull them away by the hand","Start chest compressions immediately while they touch the wire","Pour water on them","Switch off the supply or separate with a dry insulator"],3,"Rescuer safety first: break the circuit without touching the victim."],["An electrical burn should be cooled with:",["Ice packs","Running water for about 20 minutes","Toothpaste","Butter or oil"],1,"Cool running water for about 20 minutes reduces burn depth; home remedies are harmful."]]
},
{
  id:"el-equipment-maintenance-safety", title:"Care, maintenance and electrical safety testing of electrotherapy equipment", subject:"Electrotherapy", region:"Electrical safety", stages:"steps",
  aliases:["equipment maintenance","electrical safety testing","calibration of electrotherapy equipment","leakage current test","earth continuity test","Class I Class II equipment","type BF applied part"],
  simple:"Electrotherapy machines must be checked regularly so they are safe and give the dose shown on the dial. Users check plugs, leads and electrodes daily; engineers test earthing, insulation and leakage current and calibrate outputs at least yearly. Faulty equipment is labelled and removed from use.",
  flow:["Know equipment class and applied part type","Daily user checks: plug, leads, electrodes, display","Clean and store accessories properly","Periodic test: earth, insulation, leakage","Calibrate output, timer and meters","Log results, tag equipment, remove faulty units"],
  exam:[
    {h:"Classification of medical electrical equipment (IEC 60601-1)", p:["Class I: basic insulation plus protective earth on metal casing (three-pin plug); most mains SWD and stimulators.","Class II: double or reinforced insulation, no earth needed (two-pin plug, square-in-square symbol).","Internally powered: battery units (TENS, portable stimulators).","Applied part types: B (body), BF (body floating: patient circuit isolated, typical for stimulators and ultrasound) and CF (cardiac floating, strictest limits for parts that may touch the heart)."]},
    {h:"User (daily) checks", p:["Mains plug and cable intact; no cracks, burns, loose earth pin or exposed wire; strain relief at both ends.","Patient leads and electrodes: no breaks or cracked insulation, carbon rubber electrodes replaced when worn (rising resistance gives hot spots), sponges clean and evenly wet.","Controls start at zero; indicators, meters and timers work; no unusual smell, noise or heat.","Ultrasound: transducer face uncracked; simple output check with water or coupling gel (surface agitation) before use; SWD: cables and electrodes undamaged, tuning works."]},
    {h:"Periodic electrical safety tests (biomedical engineer)", p:["Visual inspection, then protective earth continuity (very low resistance, typically under about 0.2-0.3 ohm including the mains cable).","Insulation resistance between mains parts and casing (high, megaohm range).","Leakage currents: earth leakage, enclosure (touch) leakage and patient leakage, in normal and single-fault conditions; IEC 60601-1 limits for patient leakage in normal condition about 100 microamperes for B and BF parts and 10 microamperes for CF.","Frequency: on purchase (acceptance test), at least yearly (often 6-12 months for heavily used units) and after any repair, using IEC 62353 methods."]},
    {h:"Calibration and performance checks", p:["Ultrasound: output power measured with a radiation force balance; frequency, timer and duty cycle checked; effective radiating area as specified.","Electrical stimulators: pulse width, frequency, waveform and output current checked on an oscilloscope across a test load (e.g. 500 or 1000 ohm).","SWD: output and tuning, neon tube or field meter test; timer accuracy.","Iontophoresis: milliammeter accuracy; IR and UV lamps: output and lamp hours, UV test dose repeated after lamp change."]},
    {h:"Care and storage", p:["Clean electrodes and transducers after each patient with recommended disinfectant; do not soak connectors.","Coil cables loosely, never wrap tightly around the unit; store in a dry, dust-free place away from heat and sunlight.","Charge and replace batteries as advised; remove batteries in long storage to prevent leakage.","Keep an equipment register: serial number, purchase date, service history, test dates and results; follow the manufacturer's service schedule."]},
    {h:"Department safety environment", p:["Switched sockets with RCD protection; no chained extension leads or multi-plug adaptors.","Dry floors, non-metal treatment couches near SWD, SWD units sited away from other stimulators (at least 3 m is commonly advised).","Faulty equipment: switch off, disconnect, label 'Do not use', report and remove; staff trained in basic life support and incident reporting."]},
    {h:"Conclusion", p:["Routine user checks, periodic earth and leakage testing, and output calibration ensure electrotherapy equipment is both safe and accurate, protecting patients and therapists."]}
  ],
  tip:"Draw a checklist table with columns Daily (user), Periodic (engineer) and Calibration, filling three items in each. Add the symbols for Class II (square inside square) and type BF (person in a square).",
  evidence:[["Ultrasound units in clinical use often deliver output different from the display","Supports regular calibration","Moderate (equipment audits)"],["Periodic safety testing","Detects earth and leakage faults","Established safety standard"]],
  evidenceSource:"IEC 60601-1 and IEC 62353; published audits of therapeutic ultrasound calibration; Watson, Electrotherapy: Evidence-Based Practice",
  outcomes:[["Earth continuity and leakage values","Electrical safety"],["Measured vs displayed output","Calibration accuracy"],["Equipment log","Compliance with maintenance schedule"]],
  recent:["Audits of therapeutic ultrasound machines in several countries have found many units outside output tolerance, reinforcing the need for regular calibration."],
  mnemonic:{word:"CLEAN", items:[["C","Cables and plugs checked daily"],["L","Leakage current tested periodically"],["E","Earth continuity confirmed"],["A","Accuracy: calibrate output and timers"],["N","Note everything in the log and tag faults"]], extra:"BF = body floating: patient circuit isolated from earth."},
  example:"The biomedical engineer at a Chennai medical college tests the department's ultrasound with a radiation force balance and finds one unit delivering far less than its display shows; it is withdrawn until repaired.",
  flags:["Equipment past its test date or without a safety label","Cracked ultrasound head or frayed patient leads","Casing that tingles or feels warm","Displayed output not matching measured output"],
  viva:[["What is a type BF applied part?","A patient-connected part isolated (floating) from earth, used in stimulators and ultrasound."],["How is ultrasound output calibrated?","With a radiation force balance measuring output power."],["How often should electrical safety testing be done?","At acceptance, after repair and at least yearly (more often for heavy use)."]],
  refs:[{c:"International Electrotechnical Commission. IEC 60601-1 Medical electrical equipment - General requirements for basic safety and essential performance; IEC 62353 Recurrent test and test after repair of medical electrical equipment."},{c:"Watson T (ed). Electrotherapy: Evidence-Based Practice. 12th ed. Chapter: Electrical safety and equipment maintenance."},{b:"cameron", ch:"Electrical safety in electrotherapy"}],
  keywords:"equipment maintenance electrical safety testing earth continuity insulation resistance leakage current Class I Class II type B BF CF calibration radiation force balance oscilloscope IEC 60601 IEC 62353",
  mcq:[["Double-insulated equipment that needs no earth is:",["Class II","Class I","Type CF","Type B"],0,"Class II equipment relies on double or reinforced insulation."],["Ultrasound output power is calibrated using a:",["Multimeter","Neon tube","Radiation force balance","Galvanometer"],2,"The radiation force balance measures acoustic output power."]]
}
]);
